GimCorpus.put(353,0,[[1,1,"הקוצר את שדהו וכו'. כלומר שמצות הפאה להניחה בקמה כמבואר בפרק שני.",1,0],[1,1,"ומה שכתב בסוף השדה בפ״ק דפאה וטעמא איתא בפרק במה מדליקין (שבת דף כ״ג).",2,0],[1,1,"ומ״ש אחד הקוצר ואחד התולש פרק ראשית הגז (חולין דף קל״ז) ות״כ פרשת קדושים וירושלמי פ״ק דפאה:",3,0],[1,2,"וכשם שמניח בשדה כך באילנות וכו'. כן משמע במשנה רפ\"ד דפאה ובת\"כ ובירושלמי פ\"ק דפאה:",1,0],[1,2,"עבר וקצר את כל השדה וכו' עד ה״ז נותן ממנו פאה לעניים. בר״פ הגוזל עצים (בבא קמא דף צ״ד) ובפ״ק דתמורה מצות פאה להפריש מן הקמה לא הפריש יפריש מהעמרים לא הפריש מהעמרים יפריש מהכרי עד שלא מרחו מרחו מעשר ונותן לו משום ר' ישמעאל אף מפריש מן העיסה ונותן לו. ומשמע דלרבי ישמעאל אפי' אפאו מפריש ממנו ופסק רבינו כמותו משום דבעי התם ר' יונתן אליביה ועוד דאביי בעא לאוקומי התם לר' ישמעאל בשיטה ורבא דחי ליה דלעולם קסבר ר' ישמעאל שינוי קונה כסתם מתני' דהתם וכב״ה ומשמע לרבינו דלאו דיחויא בלחוד הוא אלא לקושטא דמילתא:",2,0],[1,3,"אבד כל הקציר וכו'. פרק אלו הן הלוקין (מכות דף ט״ז) וטעמא משום שאינו יכול עוד לקיים עשה שניתק לו ויתבאר פרק ט״ז מהלכות סנהדרין:",1,0],[1,4,"וכן בלקט כשקוצר וכו'. מפורש בתורה פרשת אמור.",1,0],[1,4,"ומ\"ש עבר ולקטן אפי' טחן ואפה וכו' הוא ע\"פ מה שנתבאר בפאה וכר' ישמעאל.",2,0],[1,4,"ומ\"ש אבדו או נשרפו וכו'. גם זה ע\"פ מה שנתבאר בפאה:",3,0],[1,5,"ומ\"ש וכן בפרט וכו' וכן בעוללות וכו'. הכל מבואר בתורה בפרשת קדושים.",1,0],[1,5,"ומ\"ש וכן המעמר וכו', בפרשת כי תצא.",2,0],[1,5,"ומ\"ש עבר ולקטו וכו' עד ואם לא קיים עשה שבהן לוקה. ע\"פ מה שנתבאר:",3,0],[1,6,"כשם שהשכחה בעמרים כך היא בקמה וכו'. כן משמע בפ\"ו דתנן קמה שיש בה סאתים ושכחה אינה שכחה משמע דאי הוי פחות מסאתים הוי שכחה ובספרי יליף לה מקרא:",1,0],[1,6,"וכשם שהשכחה בתבואה וכיוצא בה וכו' וה\"ה לשאר האילנות. יתבאר בסמוך:",2,0],[1,7,"נמצאת למד שארבע מתנות לעניים וכו' עד ושתים באילנות השכחה והפאה. בפ' הזרוע (חולין דף קל״א) ובתוספתא דפאה פ״ב:",1,0],[1,8,"כל מתנות עניים אין וכו' מוציאין אותן מידו. ג\"ז שם:",1,0],[1,9,"כל גר האמור במתנות וכו'. ת\"כ פרשת קדושים.",1,0],[1,9,"ומ״ש ואעפ״כ אין מונעים עניי עכו״ם וכו'. משנה פרק הניזקין (גיטין דף נ״ט):",2,0],[1,10,"נאמר במתנות עניים וכו' עד והרי אין עניים. בסוף פרק הזרוע (חולין דף קל\"ד:):",1,0],[1,11,"מאימתי מותרים כל אדם בלקט וכו'. משנה ריש פרק ח' מאימתי כל אדם מותרין בלקט משילכו הנמושות ובפרק אלו מציאות (בבא מציעא דף כ״א:) ובפ״ק דתענית (דף ו':) איפליגו ר״י ור״ל בפירוש נמושות ודברי רבינו כאן כפירוש ר״ל ויש לתמוה עליו. ומצאתי בשם הרשב״א שטעמו מפני שהוא סבור דר״י ור״ל לאו בדינא פליגי דבין הכי ובין הכי מותרים כל אדם לד״ה דבהכי עניים מתייאשים ולא איפליגו אלא בפירוש תיבת נמושות והדין עמו דאטו באתר דליכא סבי כי הני יהיו כל אדם אסורים לעולם לדעת ר״י אלא לר״י ה״ה בלקוטי בתר לקוטי ולר״ל ה״ה נמי בסבי דאזלי אתיגרא ונקט רבינו לישנא דר״ל משום דליקוטי בתר ליקוטי שכיחי בכל אתר. ועוד תדע דלאו דוקא אמרו אלא כל היכא דסמכא דעתין דמסחי עניים דעתייהו אומרים כן כאותה שאמרו בפ״ק דמציעא בפועל שמלקט בנו אחריו משום דעשאוה כהלכו בה הנמושות דעניים גופייהו מסחי דעתייהו:",1,0],[1,11,"מאימתי מותרים כל אדם בפרט וכו'. משנה בפ\"ח דפאה:",2,0],[1,11,"מאימתי מותרים כל אדם בשכחה וכו'. שם במשנה ובזיתים משתרד רביעה שניה ואמרינן בפ\"ק דתענית (דף ו') יורה במרחשון ומלקוש בניסן דברי ר\"מ וחכ\"א יורה בכסליו מאן חכמים אמר רב חסדא ר' יוסי היא דתניא אי זו היא רביעה ראשונה הבכירה בג' בחשון בינונית בשבעה בו אפילה בי\"ז בו דברי ר\"מ רבי יהודה אומר בז' ובי\"ז ובכ\"ג רבי יוסי אומר בי\"ז ובכ\"ג ובר\"ח כסליו וכו' אמר רב חסדא הלכה כר' יוסי ואמרינן עלה בשלמא רביעה ראשונה לשאול שלישית להתענות שניה למאי אמר ר' זירא לנדרים דתנן הנודר עד הגשמים משירדו גשמים עד שתרד רביעה שניה רב זביד אמר לזיתים דתנן מאימתי כל אדם מותרים בלקט וכו' ובזיתים משתרד רביעה שניה והשתא כיון דזמן רביעה שנייה לר' יוסי דאיפסיקא הלכתא כוותיה הויא בכ\"ג לחשוון ושלישית הויא בר\"ח כסליו יש לתמוה על רבינו למה כתב שרביעה שניה היא בר\"ח כסליו ואע\"פ שכתב רבינו בשנה אפילה דמשמע דאע\"ג דבשאר שנים לא הוי רביעה שניה בר\"ח כסליו בשנה אפילה הוה רביעה שניה בר\"ח כסליו איני יודע מנין לו ואין לומר שגירסתו בגמרא היה כן שהרי כתב בפ\"י מהל' נדרים שזמן רביעה שניה הוא מכ\"ג במרחשון ואילך. ונ\"ל שרבינו מפרש דר' יוסי ארביעה שניה קאי וה\"ק רביעה שניה בשנה בכירה בי\"ז ובשנה בינונית היא בכ\"ג ובשנה אפילה היא בר\"ח כסליו וכ\"כ בפירוש המשנה בפ\"ח דפאה וכן משמע מדבריו פה והטעם שתפס כאן זמן רביעה שניה בשנה אפילה משום דספק מתנות עניים להחמיר כדתנן בספ\"ד דפאה ולענין נדרים פסק דנקיטינן בשנה בינונית שדרך לשון בני אדם בדבר בינוני, ומשמע לרבינו דזמן רביעה שניה דאמרינן היינו לזיתים שבראש הזית דאלו לצבורי זיתים ששכח תחת האילן מדחזינן שהניחו עניים מלחזר אחריהם ודאי מותרים שמאחר שהם מזומנין ומונחין לפניהם ופסקו מלחזר אחריהם ודאי נתיאשו מהם דומיא דבתבואה משילכו הנמושות:",3,0],[1,12,"כל זמן שיש וכו'. נראה שזהו פירוש מה ששנינו בפ\"ח דפאה כל זמן שיש לו תחתיו יש לו בראשו ובירושלמי פתר לה תרין פתרין כל זמן שיש לו תחתיו יש לו בראשו קודם לכן אע\"פ שאין לו תחתיו יש לו בראשו פתר חורן כל זמן שיש לו תחתיו אין לו בראשו הלך המחבא אע\"פ שאין לו בראשו יש לו תחתיו. ומשמע לי דה\"פ לדעת רבינו דהני תרי פיתרי דקאמר בירושלמי היינו לומר דמתניתין לא קאי סיפא ארישא אלא תרי מילי נינהו חד כל זמן שיש לו תחתיו וחד יש לו בראשו וכאילו אמר כל זמן שיש ליטול תחתיו נוטל בכל גוונא וכל זמן שיש לו ליטול בראשו נוטל בכל גוונא אף על פי שאין לו בראשו יש לו תחתיו וה\"ק כל זמן שיש לו לעני ליטול תחתיו נוטל אף על פי שאין לו ליטול בראשו שכבר הותר לכל אדם האי הוא פירושא דרישא דקתני כל זמן שיש לו תחתיו ומאי דקתני סיפא יש לו בראשו הוי מילתא באפי נפשה וה\"ק אם יש לו לעני ליטול בראשו שעדיין לא הותר לכל אדם נוטל ואף על פי שאין לו תחתיו ולפי זה פיתרא קדמאה הוי פירושא דסיפא ופיתרא תניינא הוי פירושא דרישא ועשה כן לפרש פירושא דסיפא ברישא להורות שצריך להפריד סיפא מרישא. ולפי פירוש זה משמע לי דאפשר לומר דהא דמסיים במתני' רבי מאיר אומר משתהלך המחבא לאו מיפלג פליג אלא פירושי קא מפרש אימתי אין לו בראשו משתהלך המחבא דהיינו שחבטו העניים הזיתים בכלי שהוא משיר כל הזיתים הנחבאים במחבואו שאז הותר לכל אדם אם כן מיפלג פליג לומר דמשחבטו העניים בכלי המשיר כל הזיתים הנחבאים הותר לכל אדם השאר ולתנא קמא לא הותר עדיין:",1,0],[1,12,"והראב\"ד כתב א\"א בחיי ראשי אינה נראית לא כדברי הרב המחבר ולא כדברי הרב היוני וכו'. ורש\"י פירש בע\"א:",2,0],[1,13,"מתנות עניים וכו'. ירושלמי רפ\"ח דפאה:",1,0],[1,14,"כל מתנות עניים האלו וכו' הרי הכתוב אומר ובקצרכם את קציר ארצכם וכו'. ירושלמי פ\"ג דפאה.",1,0],[1,14,"ומ״ש וכבר נתפרש בגמ' שהפאה נוהגת בח״ל מדבריהם, נ״ל דהיינו מדאמרינן בס״פ הזרוע (חולין דף קל״ד:) לוי זרע בכישא ולא הוו עניים למשקל לקט אתא לקמיה דרב ששת א״ל לעני ולגר תעזוב אותם ולא לעורבים ולעטלפים משמע דבח״ל הוה מדאתא לקמיה דרב ששת דהוה בבבל:",2,0],[1,15,"כמה הוא שיעור הפאה וכו'. במשנה פרק קמא דפאה.",1,0],[1,15,"ומה שכתב בין בארץ בין בח\"ל. בפרק ראשית הגז.",2,0],[1,15,"ומה שכתב ומוסיף על האחד מששים לפי גודל השדה וכו'. משנה בפרק קמא דפאה.",3,0],[1,15,"ומ\"ש כיצד שדה שהיא קטנה ביותר וכו'. שם בירושלמי.",4,0],[1,15,"ומה שכתב וכל המוסיף על הפאה וכו' אהא דתנן בריש פאה אלו דברים שאין להם שיעור קאמר בירושלמי ולמה לא תנינן עפר סוטה ואפר פרה ומשני לא מיתניא במתני' אלא דברים שהוא מוסיף עליהם ויש בעשייתן מצוה אלו אע\"פ שמוסיף אין בעשייתן מצוה:",5,0],[2,1,"כל אוכל שגידוליו מן הארץ וכו' עד ומכניסין אותו לקיום. משנה בפ\"ק דפאה ומפרש לה בגמרא סוף פרק מקום שנהגו ופרק כלל גדול (דף נ') ופרק בא סימן (דף ס\"ח) וממעט מינה כל הדברים שממעט רבינו:",1,0],[2,2,"ומ\"ש השומים והבצלים חייבים בפאה. במשנה פ\"ו דפאה (דף ט') וכת\"ק ונתבאר פ' בא סימן (נדה נ') ממשנה אחרת.",1,0],[2,2,"ומ\"ש וכן האמהות של בצלים וכו'. משנה בפ\"ג דפאה וכת\"ק:",2,0],[2,3,"קרקע כל שהוא חייבת בפאה. משנה שם וכר\"ע.",1,0],[2,3,"ומה שכתב ואפילו היתה של שותפים וכו'. ר״פ ראשית הגז (חולין דף קל״ה):",2,0],[2,4,"שדה שקצרוה נכרים לעצמם וכו' עד נותן פאה לכל. משנה פ\"ב דפאה (משנה ז' ח') ודקדק רבינו לכתוב גבי קצרוה נכרים לעצמם ללמד דאילו קצרוה לישראל חייב כדאיתא בירושלמי:",1,0],[2,5,"ומ\"ש קצר חציה והקדיש חציה וכו'. שם.",1,0],[2,5,"ומ\"ש קצר חציה והקדישו וכו'. תוספתא פירקא קמא דפאה:",2,0],[2,6,"כרם שהיה וכו'. זהו לדעת רבינו פירוש מה ששנינו בפ\"ג דפאה בכרם המדל נותן מן המשואר על מה ששייר והמחליק מאחת יד נותן מן המשואר על הכל וז\"ל רבינו שם בפירושה כרם המדל כרם מדולדל גזור ממלת דל והוא שיבצור מקצתו וימכור ויעזוב הנשאר לדרוך או ליבש אמר שחייב לתת פאה מהשארית הנשארת כפי מה שנשאר לא כפי הכרם כולו וזהו כשיבצור הענבים מכל צד מצדי הכרם אבל כשיבצור מצד אחד ומכר והניח הנשאר יתן ממה שנשאר פאה המחוייב לכל הכרם וזהו פירוש מה שאמר המחליק מאחת יד ר\"ל הבוצר מצד אחד עכ\"ל.",1,0],[2,6,"ומ״ש וכן כל הקוטף מלילות מעט מעט וכו'. ירושלמי שם אכתבנו בספ״ד ותוספתא פ״ק דפאה ואע״ג דגמרא דידן פרק ראשית הגז (חולין דף קל״ז) אמרינן דרבי יוסי הוא דסבר הכי ופליגי רבנן עליה כתב הר״ן דפסק כר' יוסי משום דשקלי וטרו אמוראי אליביה אלא דק״ל דא״כ ה״ל למיפסק בתולש צמר רחלים בידו דפטור כר' יוסי דאמרינן בגמרא דפטור כי היכי דפטר תולש מפאה והוא ז״ל פסק בפ״י מהלכות בכורים דחייב והניח הר״ן הדבר בצ״ע. ואני אומר שעל מה שכתב הר״ן שפסק רבינו כר' יוסי משום דשקלי וטרו אמוראי אליביה יש לדון שלא אמרו שם אלא מודה רבי יוסי במידי דאורחיה וכו' והאי לאו שקלא וטריא הוא. לכך נ״ל שלא פסק רבינו כר' יוסי במתנות עניים אלא משום דבירושלמי ובתוספתא סבר בהו כוותיה אבל בראשית הגז דלא אשכחן דסבר כוותיה הדרינן לכללין דאין הלכה כיחידאה ואע״ג דבגמ' דידן מדמי תולש צמר לקיטוף מלילות אינו מוכרח ואפשר לחלק ביניהם:",2,0],[2,7,"הקוצר כל שדהו וכו'. ירושלמי פרק שלישי:",1,0],[2,8,"המקדיש שדהו וכו' עד שאינו חייב בפאה. משנה בפרק רביעי דפאה ודריש לה בספרי מקרא:",1,0],[2,9,"נכרי שקצר שדהו וכו'. גם זה משנה שם וכתנא קמא:",1,0],[2,10,"אין שוכרים פועלים עכו\"ם לקצור וכו'. ירושלמי בפ\"ב דפאה ותוספתא פ\"ג:",1,0],[2,11,"בעה״ב שקצר כל שדהו וכו' ואינו צריך לעשר וכן אם דש וכו' וגמר מלאכתו מעשר וכו'. בפ' הגוזל עצים (בבא קמא דף צ״ד) ובפ״ק דתמורה (דף ו') ובמשנה פ״ק דפאה לעולם הוא נותן משום פאה ופטור מן המעשרות עד שימרח כלומר אבל משמרח אע״פ שנותן משום פאה חייב במעשרות:",1,0],[2,11,"ומ\"ש ואם נתן להם רוב הקציר משום פאה וכו'. אהא דתנן בפ\"ג דפאה ר\"ע אומר קרקע כל שהוא חייב בפאה קאמר בירושלמי הגע עצמך שהיה שם שבולת אחת עד שלא קצר אין כאן חיוב משקצר אין כאן שיור (ר' חנניה בשם ר' פנחס תיפתר) בשהיה שם קלח אחד ובו ה' שבלים. וכתב סמ\"ג וז\"ל קרקע כל שהו חייב בפאה מקשה בירושלמי והלא צריך בקוצר שיקצור לעצמו שום דבר ולפיכך שנינו בתוספתא העושה כל שדהו פאה אינה פאה והא דתניא בפ\"ק דנדרים מנין שאם רצה לעשות כל שדהו פאה שהרשות בידו תלמוד לומר פאת שדך כל שדהו לאו דוקא וכ\"כ שם התוספות:",2,0],[2,12,"אין מניחים את הפאה אלא בסוף השדה וכו' עד ויתננה לעני הקרוב לו. תוספתא בפרק קמא דפאה וירושלמי בפ״ד דפאה ומייתי לה בפרק במה מדליקין (שבת דף כ״ג) ואע״ג דר״ש אמרה אפשר דמפרש רבינו דלא פליג את״ק וכמו שפירשה רבינו שמשון ואפילו את״ל דפליג פוסק כר״ש כיון שנתן כמה טעמים לדבר. ועוד י״ל שרבינו מפרש דהא דתני ת״ק נותנים פאה מתחלת השדה ומאמצעה בדיעבד קאמר לומר ששם פאה עליו אבל לכתחלה לכ״ע אין נותנים אלא מסוף השדה.",1,0],[2,12,"ומה שכתב עבר והניח הפאה בתחלת השדה וכו'. משנה בפ\"ק דפאה נותנין פאה מתחלת השדה ומאמצעיתו ר\"ש אומר ובלבד שיתן בסוף כשיעור ר' יהודה אומר אם שייר קלח אחד סומך לו משום פאה ואם לאו אינו נותן אלא משום הפקר ופסק רבינו כר\"ש וצריך טעם למה ואפשר דסבר דלא פליג את\"ק אלא מפרש דבריו ור' יהודה פליג אתנא קמא. ומפרש בירושלמי דכשיעור דאמר ר\"ש לא כשיעור כל שדהו קאמר אלא כשיעור המשתייר ואפילו את\"ל דר\"ש פליג את\"ק פסק כר\"ש משום דבירושלמי מפרש מילתיה אלמא סבר דהלכתא כוותיה:",2,0],[2,13,"בעל הבית שנתן וכו'. תוספתא דפאה פ\"ב ואיתא בפרק המניח:",1,0],[2,13,"וכן בעל השדה שהפריש וכו'. בפ\"ק דנדרים (דף ו':) בעי רב פפא יש יד לפאה או אין יד לפאה ה\"ד אילימא דאמר הדין אוגיא להוי פאה והדין נמי ההיא פאה מעלייתא היא אלא דאמר והדין ולא אמר נמי ובתר הכי בעי אם יש יד לצדקה ופירש הר\"ן דמיבעיא ליה באת\"ל יש יד לפאה. ודעת רבינו לפסוק כאת\"ל דאע\"פ שכמדומה לי שכשאין האת\"ל מפורש בגמרא אינו פוסק כמותו מ\"מ י\"ל כיון דלא איפשיטא הוי ספיקא דאורייתא ולחומרא וכן פסקו הרמב\"ן והרשב\"א:",2,0],[2,14,"אסור לפועלים לקצור את כל השדה וכו' עד אסור ליגע בה. בתוספתא דפאה פ\"ב:",1,0],[2,15,"הפאה של תבואה וקטניות וכו' עד ובמנחה. הכל משנה פ\"ד דפאה:",1,0],[2,16,"ומ\"ש ומחייבין בעה\"ב להוריד ולחלקה ביניהם. שם בירושלמי:",1,0],[2,17,"ומ\"ש ולמה לא קבעו לה עת אחר ביום וכו'. שם בירושלמי:",1,0],[2,18,"עני שנטל מקצת הפאה וכו'. משנה שם נטל מקצת פאה וזרק על השאר אין לו בה כלום נפל לו עליה פירש טליתו עליה מעבירין אותה הימנו. ובתוספתא נטל מקצת פאה וזרק עליה אין לו בה כלום ר\"מ אומר קונסין אותו ונוטלים הימנו זו וזו ומפרש רבינו דכולה ר\"מ היא וה\"ק שר\"מ אומר כ\"כ הר\"ן בריש מציעא שזה דעת רבינו:",1,0],[2,19,"מי שלקח את הפאה וכו'. משנה שם מי שליקט את הפאה ואמר הרי זו לאיש פלוני עני ר' אליעזר אומר זכה לו וחכ\"א יתננה לעני שנמצא ראשון ופסק כחכמים וכעולא דאמר בפ\"ק דמציעא (דף ט':) דהני מילי מעשיר לעני אבל מעני לעני ד\"ה זכה לו:",1,0],[2,20,"בעל הבית שהניח פאה וכו'. תוספתא דפאה פ\"ב וירושלמי פ\"ד:",1,0],[3,1,"אין מניחין את הפאה וכו'. ירושלמי פרק שני דפאה ובתורת כהנים יליף לה מקרא.",1,0],[3,1,"ומה שכתב ואם הניח משדה על חבירתה אינה פאה. ירושלמי בפרק שני דפאה והכי משמע בפרק הכונס ובפרק חזקת:",2,0],[3,2,"ומ\"ש היתה שדהו זרועה כולה מין אחד וכו' עד או שקצר באמצעה וכו'. הכל משנה בפרק שני דפאה.",1,0],[3,2,"ומ\"ש גבי נחל אע\"פ שאינו מושך וגבי אמת המים שתהיה מושכת. שם בירושלמי.",2,0],[3,2,"ומ\"ש באמת המים שאינו יכול לקצור מה שבשני צדדיה כאחת. במשנה הנזכרת אמת המים שאינה יכולה להקצר כאחת ר' יהודה אומר מפסקת ולכאורה משמע דת\"ק פליג עליה ומדפסק רבינו כר' יהודה נ\"ל שהוא מפרש דד\"ה היא ונכתב בשם ר' יהודה משום דהוא אמרה בי מדרשא ואתא לפרושי שלולית דתנא ברישא דמפסקת דהני מילי בשאינה יכולה להקצר כאחת. וז\"ל רבינו בפירוש המשנה ענין שאינה יכולה להקצר כאחד כשיהיה בצד אחד לא יוכל לשלוח ידו ולקצור מצד אחר וכו' והלכה כרבי יהודה עכ\"ל. והתוספתא פ\"ק תניא אלו מפסיקין לפאה וכו' ואמת המים שאינה יכולה להקצר כאחד אר\"י אם עומד באמצע קוצר מכאן ומכאן מפסיק ואם לאו אינו מפסיק וה\"פ כיון שאם עומד בצד אחד לא יוכל לקצור הצד השני אע\"פ שאם עומד באמצע קוצר השני צדדים מפסיק ואם לאו פירוש שאין צריך לעמוד באמצע אלא מהצד האחד קוצר השני אינו מפסיק. ובירושלמי הוון בעי מימר ולא פליגין אשכחת תני אמת המים הקבועה הרי זו מפסקת הוון בעון מימר מה דאמר ר\"י בעומד מצד זה ואינו יכול לקצור מצד השני אבל אם היה עומד באמצע וקוצר מכאן ומכאן אינו מפסיק אשכחת תני ופליגי (דתניא) היה עומד באמצע וקצר מכאן ומכאן מפסיק מצד אחד אינו מפסיק. ונ\"ל דהכי פירושו לדעת רבינו הוון בעי מימר ולא פליגין. האי פליגין לאו לשון מחלוקת חכמים הוא אלא היינו לומר שאין חלוק בדבר שכל אמת המים מפסקת בין קבוע בין אינו קבוע עד שמצאו דתניא דדוקא קבועה מפסקת ולא שאינה קבועה. ומ\"ש הוון בעון מימר מאי דאמר ר\"י וכו' אבל אם היה עומד באמצע וקוצר מכאן ומכאן אינו מפסיק אשכח תני ופליג כלומר מצאו ברייתא שחולקת עם זאת הסברא דתניא היה עומד באמצע וקוצר מכאן ומכאן מפסיק וכו' והיא התוספתא שכתבתי בסמוך וכמו שפירשתיה וככה עלו דברי רבינו כדין וכהלכה על פי התוספתא והירושלמי. ודע דבפרק הכונס (ב\"ק ס\"א) אמרינן דשלולית היינו אמת המים המחלקת שלל לאגפיה. ויש לתמוה למה לא כתב כן רבינו ואפשר שרבינו מפרש כאן במחלקת שלל לאגפיה היינו שהיא מושכת מים שעל ידי כן הצדדים שלה מובלעים מים וכאילו חולקת להם שלל לאפוקי נחל שאמרו בו שאע\"פ שאינו מושך. ואע\"פ שבפירוש המשנה פירש דמחלקת שלל לאגפיה היינו שנמשכים ממנה אמות המים להשקות בהם מקומות אחרים כאן חזר בו משום דקשיא ליה דנחל שיש בו מים היא ע\"כ דאין לומר דבאין בו מים מיירי מלשון נחל איתן דהיינו בור וכבר שנאו ותרתי למה לי וכיון דכשיש בו מים מיירי מאחר דקתני דמפסיק אע\"פ שאין נמשכים ממנו אמות המים אמאי איצטריך למיתני שלולית שנמשכים ממנה אמות המים דהא מכ\"ש אתיא לכך פירש מחלקות מים לאגפיה כענין שפירשתי וה\"ה הנחל בין שהמים נמשכים בין שאינם נמשכים ומי יימר דדא אמת המים ועוד דנחל מיירי אפי' באינו מושך ולא רצה לידחק במה שנדחק רבינו שמשון לומר דלא זו אף זו קתני:",3,0],[3,3,"ומה שכתב רבינו שדרך היחיד ארבע אמות ודרך הרבים שש עשרה אמה. משנה בפרק המוכר פירות (ב\"ב צ\"ט:):",1,0],[3,3,"וכתב הראב\"ד אבל שביל היחיד והוא הפחות מד' א\"א לא כי אלא אפילו יש לו ארבע אמות וכו'. ורבינו משמע ליה דשביל היחיד הוא צר מדרך ולכך של יחיד שיעורו פחות מד' שהוא דרך היחיד ושביל של רבים פחות מט\"ז שהוא דרך הרבים ובירושלמי (פ\"ב ה\"א) מכיון דתנינן דרך היחיד (דרך הרבים) מה צורכה (אנא מימר לך) אפילו דרך הרבים אינו מפסיק לאילן (אלא גדר) מכיון דתנינן שביל היחיד שביל הרבים מה צורכה להוציא את הקבוע בימות החמה ואינו קבוע בימות הגשמים:",2,0],[3,4,"ומ\"ש או שקצר באמצעה וכו'. שם במשנה הקוצר לשחת מפסיק דברי ר\"מ וחכ\"א אינו מפסיק אא\"כ חרש וידוע דהלכה כחכמים. ולשון אפילו קשה דאדרבה מפני שלא הביאה שליש לא נקרא קצירה היה ראוי להפסיק יותר מכשנקצר אחר שהביאה שליש דאז י\"ל התחלת קצירה היא כדמשמע במנחות פרק ר' ישמעאל. ואפשר לומר שמפני שכתב אח\"כ וחרש כתב אפילו כלומר דאפילו קצר קודם שהביאה שליש בעינן חרש:",1,0],[3,4,"ומ\"ש והוא שיהיה רוחב כל אחד מאלו כשלשה תלמים של פתיח. שם בירושלמי.",2,0],[3,4,"ומה שכתב והוא פחות מבית רובע. כן משמע שם בירושלמי.",3,0],[3,4,"ומה שכתב בד\"א בשדה קטנה וכו'. גם זה שם בירושלמי.",4,0],[3,4,"ומה שכתב אא\"כ היה בו רוחב בית רובע. גם זה משמע שם בירושלמי.",5,0],[3,4,"ומ\"ש אבל זרע אחר כל שהוא מפסיק בה. בירושלמי רב אמר בור וניר בית רובע וזרע אחר אפי' כל שהוא ר\"י אומר בור וניר וזרע אחר כשלשה תלמים של פתיח מה ופליג מה דאמר רב בחיוב פאה ומה דאמר ר\"י בפיטור פאה והתני בור וניר חייבים בפאה מן מה דאמר רב בשדה בינונית מן מה דאמר ר' יוחנן בחמשים על שתים עכ\"ל הירושלמי. ומדקתני בור וניר חייבים בפאה והיינו בחמשים על שתים ושבקיה לזרע אחר משמע דזרע אחר כל שהוא כדקאמר רב וכיון דברייתא מסייעא ליה נקיטינן כותיה ולא כר\"י דאמר זרע אחר בשלשה תלמים של פתיח:",6,0],[3,4,"כתב הראב\"ד באמת אין הגירסא מתנהגת כדבריו אמרו בירושלמי רב אמר בור וניר בית רובע וכו' עד כי הדדי נינהו. וכבר כתבתי טעם לדברי רבינו וכך היא גירסת ר\"ש בירושלמי וגירסת הראב\"ד נראה שיש בה ט\"ס:",7,0],[3,5,"אכלה גובאי או וכו'. ירושלמי שם ואיתא במנחות סוף פרק רבי ישמעאל (מנחות דף ע״א:):",1,0],[3,6,"הזורע בהר שאינו וכו'. משנה בפ\"ב וכל ההרים אשר במעדר יעדרון אע\"פ שאין הבקר יכול לעבור בכליו הוא נותן פאה לכל. ודברי רבינו כאן בזה כדבריו בפירוש השני בפירוש משנה זו:",1,0],[3,7,"מדרגות שהן גבוהות וכו' עד אינו מפסיק. שם ובירושלמי חייא בר אדא בשם ר\"ל היה שם סלע ע\"פ כל שדהו אם עוקר הוא את (כל) המחרישה מצד זה ונתנו מצד זה מפסיק מצד אחד אינו מפסיק והתני מדרגות שהן גבוהות י' טפחים נותן פאה מכל אחת ואחת פחות מכאן נותן מאחת על הכל ופחות מכאן אינו עוקר את המחרישה מצד זה ונותנה מצד אחר אפילו פחות מכאן עוקר הוא לא אתינן מיתני י' אלא בגין סופה שאם היו ראשי מדרגות מעורבין שהוא נותן מאחת על הכל. ומשמע דה\"פ אה\"נ שכל שהוא צריך לעקור את המחרישה מצד זה וליתנה בצד אחר אע\"פ שהן פתוחות מי' מפסיק ולא נקט י' אלא משום סיפא. ולפי זה מאי דתני פחות מכאן נותן מאחת על הכל אינו מלשון הברייתא. ויש הוכחה לדבר דבתוספתא דאייתי האי ברייתא ליתיה חלא מדברי המקשה הוא דדייק הכי וא\"כ יש לתמוה על רבינו שפסקה בסמוך לדר\"ל וכאן גבי מדרגות כתב שאם היו פחות מעשרה נותן מאחת על הכל והרי אלו תרתי דסתרן. וצ\"ל שרבינו סבר שיש לחלק בין סלע שאינו ראוי לזריעה למדרגות שהן נזרעות ולפיכך כל שהן פחות מעשרה אינו מפסיק והמקשה לא דק לחלק חילוק זה והמתרץ השיב לו לפי דרכו ואמר לו לפי מה שעלה בדעתך להשוותם יש לתרץ דלא נקטה אלא משום סיפא אבל לפום קושטא לא דמו כלל וכמו שחילקתי ודרך זה נהגו בגמרא וכדאמרינן פ\"ה דפאה גבי שבולת של לקט שנתערבה עם הגדיש ובפ\"ט דשביעית גבי מי שהיו לו פירות שביעית שנפלו לו בירושה ובפ\"ק דמציעא גבי מי שליקט את הפאה ובכמה דוכתי והשתא שפיר עביד רבינו דפסקה לדר\"ל וכתב בההיא דמדרגות שאם היו פחות מעשרה נותן מאחת על הכל. ועי\"ל ע\"פ דרך זה דבענין אחר יש להקל בין סלע למדרגות דסלע מיירי כשהוא על פני כל שדהו ומדרגות מיירי שאינה על פני כל השדה:",1,0],[3,8,"הזורע שדה שיש בה אילנות וכו'. משנה ריש פ\"ג דפאה וכב\"ה:",1,0],[3,9,"ומ\"ש בד\"א בשהיו האילנות וכו'. שם בירושלמי:",1,0],[3,9,"וכתב הראב\"ד א\"א אינו כן בגמרא דירושלמי וכו'. וגירסת רבינו בירושלמי נראה שהיתה מהופכת והיא יותר נכונה דבמרווחין נותן פאה מכל אחד לפי ששיעור כל מלבן הוא גדול וכדאי להיות שדה בפני עצמו וכשהן מפוזרים כל מלבן שיעורו קטן ואינו כדאי להיות שדה בפני עצמו ואילו לגירסת הראב\"ד בירושלמי הוי איפכא וכשהרגיש הראב\"ד חולשת גירסתו השתדל לבקש לה פנים:",2,0],[3,10,"וכן מלבנות הבצלים וכו'. משנה שם ופסק כחכמים:",1,0],[3,11,"שדה שכולה זרועה מין אחד וכו'. משנה שם המנמר את שדהו ושייר קלחים לחים ר\"ע אומר נותן פאה מכל אחד ואחד וחכ\"א מאחד על הכל ומודים חכמים לר\"ע בזורע שבת או חרדל בג' מקומות שהוא נותן פאה לכל אחד ואחד:",1,0],[3,12,"ומ״ש בד״א בשהיה יבש מכאן ויבש מכאן וכו'. שם בירושלמי עד כדון כשהיה יבש מכאן ומכאן ולח באמצע היה לח מכאן ומכאן ויבש באמצע רבי בא בר חייא בשם ר״י אתיא דר״מ בשיטת ר״ע רבו (כמו דר״ע) אמר לח ויבש שני מינים כן ר' מאיר אומר לח ויבש שני מינין (הם) ומשמע דהא דלח מכאן ומכאן ויבש באמצע בעיא ולא איפשיטא היא דהא דא״ר בא בר חייא מילתא באפי נפשה היא לפרושי מילתא דר״ע וא״כ קשה למה פסקה רבינו בפשיטות וכבר השיגו הראב״ד וכתב עירבובי דברים יש כאן ולא הסכים להלכה וכו'. ולי נראה שרבינו מפרש דלאו בעיא היא אלא ה״פ עד כדון לא אמרי רבנן מאחד על הכל אלא בשהיה יבש מכאן ומכאן ולח באמצע דכיון שהוא יבש מכאן ומכאן חשיב כאילו כולו יבש דמה שבאמצע בטל לגבי מה שבצדדין אבל אם היה לח מכאן ומכאן ויבש באמצע כיון שהוא לח מכאן ומכאן א״א לחשבו כאילו כולו יבש וממילא משמע דמודו לר״ע בהא דפאה מכל אחד ואחד ואפילו את״ל שהיא בעיא דלא איפשיטא שפיר דמי למיפסקה לחומרא דספק מתנות עניים אזלינן בהו לחומרא כדאיתא בסוף פרק ד' דפאה. ומ״ש ולא ידעינן הא דר״מ היכן היא עם היות שהראב״ד היה סוקר כל הגמרות בסקירה אחת פה נעלם ממנו אי זה מקום דבר זה כי הלא הוא במנחות פרק רבי ישמעאל (מנחות דף ע״א:) גמרא ערוכה והוא ז״ל כתבו בלשון י״א ונראה מדבריו שהוא דוחה אותו:",1,0],[3,12,"ודע דבירושלמי מסיים בה הכי אמרי חברייא קומי רבי יוסא ולמה לי כרבי עקיבא אפילו כרבנן דתנינן המחליק בצלים לחים לשוק ומקיים יבשים לגורן (נותן פאה לאלו לעצמן ולאלו לעצמן) אמר רבי יוסא שמעינן שוק וגורן שני מינים לח ויבש שני מינים. וכתב ה\"ר שלמה שיביל\"יו ז\"ל בפירושו לירושלמי עד כדון שהיה יבש מכאן ומכאן ולח באמצע הכא סברה הגמרא כרבי יוחנן פרק ר' ישמעאל דמנחות דבמנמר לאוצר עסקינן שהוא מבושל כל צרכו ומיבעיא ליה אליבא דרבנן דאמרי מאחד על הכל ונותן מן הלח על היבש ע\"כ אין לנו לפרש אלא דמשייר היינו שהוא מועט כגון שלוקט מכאן ומכאן המבושל ונשתייר הלח באמצע כרבי עקיבא כיון דדמי לערוגה בפני עצמה לא מצטרף ולרבנן סוף קצירה והכי דייק לישנא דמתניתין דקתני ושייר קלחים לחים משמע דהלח הוי שיריים. היה לח מכאן ומכאן ויבש באמצע מהו כלומר שהיה לח מרובה כגון שהיה המבושל באמצע וקצר היבש והניח הלח עם היבש מי אמרינן נמי הכא דטופלין הלח עם היבש. אתיא דרבי מאיר כשיטת רבי עקיבא רבו. ונראה בעיני דאייתי הגמרא מימרא דרבי בא לשנויי בעיין וה\"ק דר\"י אמר עלה דההיא דר\"מ דקוצר לשחת דאתיא כרבי עקיבא דהכא דכי היכי דלרבי עקיבא דמתני' לח ויבש ב' מינים וחשיב ליה כמו זרע אחר ולהכי יהיב פאה מן המבושל לחוד ומן הלח לחוד ומבושל כיון דאפסקיה לא יהיב על כל מבושל ומבושל וכי הדר קצר הלח נמי יהיב פאה על כל לח ולח דאפסקיה מבושל ה\"נ לרבי מאיר דס\"ל דכי קצר באמצע לשחת דהיינו שהביא שליש וכדאמר לעיל ושייר האחד כדי שיתבשל כל צרכו כי הדר קצר ליה כי הוי יבש הוי הנימור של אמצע שקצרו בפעם ראשונה דמי לאחשביה ללח מכאן ולח מכאן וזה שקצר באמצע דמי ליבש באמצע הילכך לא מצטרף יבש של כאן ליבש של כאן אלא בנותן פאה מכל אחד ואחד וכיון דרבי מאיר בשיטת ר\"ע אמרה וכך הוא נימור השחת כיון דהביא שליש כמו נמור דיבש דטעמא הוא משום דחשיב ליה מין אחר איפשיטא בעיין דלעולם פליג ר\"ע ונותן פאה מכל אחת ואחת ולרבנן מאחד על הכל דהתם המשוייר הוי רובא דקוצר לשחת דקתני דומיא דדרך היחיד וכו' ולמה לי כר\"ע למה לן לדחוקי נפשין ולמיפשט מדאוקימנא כר\"ע ותילף מרבנן דהתם בעיא דילן מאחד על הכל תילף מרבנן גופייהו איפכא דכי קצר לבסוף ללח חייב על זה בפני עצמו וכו' דתנן המחליק בצלים וכו' דהיינו שעקרן ומסיר הקליפות שאינו אוכל ומוציא אותם לשוק כדי שיאכלם כשהם לחים בעלים שלהם ומקיים יבשים לגרן מעמיד בקרקע אותם הראויים להתקיים דהיינו להיות יבשים ומשהה אותם שם כדי שיגדלו כל צרכו ויהיו מבושלים דהיינו דמניח הלח שיתבשל דנדון דידן ותנן דנותן פאה לאלו לעצמן ומסתמא מקיים יבשים לגורן דהוי רובא ומשמע דלרבנן כי לקיט הלח ומשייר האחר שיתייבש כל צרכו דהוי רובא שני מינים חשיב לגבי דיהיב תחלה ללח בפני עצמו ולסוף ליבש בפני עצמו אבל לגבי יבש עצמו אפילו יהא מופסק יהיב לכוליה יבש כאחד דהא לא אשכחן לרבנן טפי אלא ר\"מ לחודיה הוא דאית ליה הכי והדר רבי יוסא לתלמידיו דמהך מתניתין שמעינן דשוק וגורן שני מינים אבל לח ויבש שיהו ב' מינים לרבנן לא שמעינן לח ויבש שני מינים בתמיה כלומר מי שמעינן ופסק הרמב\"ם בפרק ג' ממתנות עניים כדברי חבריא שכתב אבל לח מכאן ומכאן וכו' דס\"ל דמאי דא\"ר יוסא דשוק וגורן דוקא דליתא אלא משל בעלמא הוא והכי אמרינן לעיל פ\"ב. ודברי הראב\"ד בזה אינם נוחים אצלי כלל ודברי הרמב\"ם נכונים בעיני עכ\"ל:",2,0],[3,13,"שדה שזרעה וכו'. גם זה שם משנה המחליק בצלים לחים לשוק ומקיים יבשים לגורן וכו':",1,0],[3,14,"הזורע את שדהו וכו'. משנה בפרק ב' דפאה:",1,0],[3,16,"האחין שחלקו נותנין וכו'. משנה פ\"ג דפאה:",1,0],[3,16,"השותפין שקצרו וכו'. שם בירושלמי קצר חצי שדה בשותפות וחלקו אינו מפריש משלו לא בתחלה ולא בסוף חזרו וחלקו ונשתתפו וקצרו חצי שדה בשותפות וחלקו (אינו) מפריש שבסוף על חבירו שבסוף אבל לא משלו שבתחלה לחבירו שבתחלה. פי' אותו שלקח הקציר אינו מפריש לא מקציר וגם לא בסוף דהיינו מהחצי שבקמה. והטעם דבשעת קצירת החצי לא נתחייב בפאה דחיוב הפאה בסוף ובשעה שקצר החצי השני אין לחבירו חלק בו ולא לזה חלק במה שנקצר דכיון שהיו שותפין איגלאי מילתא שזהו חלקו ולא נטל אלא חלק המגיע לו ולכך לא יניח אלא חלק המגיע לחלקו חזרו ונשתתפו וקצרו החצי השני בשותפות כל אחד חייב להפריש מן הקמה גם על חלק חבירו של הקמה וזהו שבסוף על חלק חבירו שבסוף כי החלק השני קורא שבסוף והחצי האחד שנקצר בתחלה נקרא שבתחלה דכיון שנפטר אותו חצי בעת שחלקו נפטר ואינו חוזר לחיובו:",2,0],[3,17,"שדה שהגיע וכו'. ירושלמי שם אמר רבי יהושע בן לוי היתה לו שדה אחת חציה הביאה שליש וחציה לא הביאה ולא הספיק לקצור חצי חצייה עד שהביאה כולה שליש מפריש מן הא' על האמצעים ומן האמצעים על הא' ואינו מפריש מן הא' על הא' ולשון זה נראה שאין לו הבנה. והר\"י קורקוס ז\"ל גורס בכל הני א' ראשון ופירש אבל לא מן הראשון דהיינו רביע א' שקצר על הראש האחר כי במה שקצר אותו רביע עדיין לא הביא שליש האחרון ולא היה נקרא תבואה. וה\"ר שלמה אישביל\"י ז\"ל (גורס כגירסא דידן) פי' ולא הספיק לגמור חצי חציה של אותו שהביא שליש מפריש מן הראשון על האמצעי דחשיב כילוי האמצעי לגבי ראשון דרמי חיובא עליה ומפריש מן הראשון על האמצעי דאמצע חשיב כלוי בהדי ראשון ומן האמצעי על הראשון וכל שכן מן האחרון על האמצעי דהא הוי האמצעי בקמה בשעה שנתחייב האחרון דכולה חדא שדה ומצטרפת ואינו מפריש מן הראשון על הראשון דחובת פאה בקמה ואינו מפריש מן הקציר על הקציר אלא היכא דכילה עכ\"ל:",1,0],[3,18,"המוכר מקומות וכו'. משנה (פאה פ\"ג מ\"ה) המוכר קלחי אילן בתוך שדהו נותן פאה מכל אחד ואחד א\"ר יהודה אימתי בזמן שלא שייר בעל השדה אבל אם שייר בעל השדה הוא נותן פאה לכל וכבר נודע שכל מקום שאמר ר\"י אימתי אינו חולק אלא מפרש דברי חכמים וכן כתב רבינו בפירוש המשנה שר\"י הוא מבאר ואין חולק עליו והא דאמרינן בס\"פ ראשית הגז מאן תנא דהיכא דאיכא שיורא גבי מוכר בתר מוכר אזלינן אמר רב חסדא ר\"י הוא לאו למימרא דאיכא מאן דפליג עליה אלא מפני שהוא היה בעל מאמר זה בבית המדרש אע\"פ שלא נמצא מי שחלק עליו נקרא בשמו ובס\"פ ראשית הגז מסקי רב חסדא ורבא דהא דא\"ר יהודה אם שייר בעל השדה הוא נותן פאה לכל והוא שהתחיל בעל השדה לקצור משום דכתיב ובקצרכם מעידנא דאתחיל לקצור מיחייב בכולה שדה.",1,0],[3,18,"ומ\"ש עוד רבינו ואם מכר תחלה מפריש הלוקח וכו'. פשוט הוא:",2,0],[3,21,"שדה אילן וכו' עד ופאה אחת לכולן. משנה פרק ב' דפאה ודלא כרבי אליעזר בר צדוק:",1,0],[3,21,"וכתב הראב\"ד א\"א לא ידעתי מהו זה וכו'. ואין פירושו מוכרח ויש מקום לפירוש רבינו:",2,0],[3,21,"ומה שכתב היו שני הצדדים רואים את האמצעיים וכו'. ירושלמי שם:",3,0],[3,22,"הזיתים כל מה שיש מהן ברוח אחת וכו'. שם במשנה:",1,0],[3,23,"הבוצר מקצת כרמו וכו'. משנה בפרק ג' דפאה המידל נותן מהמשואר על מה ששייר והמחלק מאחר יד נותן מהמשואר על הכל. ובירושלמי נותן מהמשואר על מה ששייר תני א\"ר יודא בד\"א במידל לשוק אבל במידל לבית נותן מהמשואר על הכל א\"ר זעירא הדא דתימא בשעיבה ע\"מ להדל אבל אם עיבה ע\"מ שלא להדל לא סוף דבר לביתו אלא אפי' לשוק נותן מהמשואר על הכל.",1,0],[3,23,"ומ\"ש רבינו כבר בארנוהו. בפ\"ב:",2,0],[4,1,"אי זהו לקט וכו'. משנה בפ\"ד דפאה.",1,0],[4,1,"ומ\"ש והוא שיהיה הנופל שבולת אחת או שתים וכו'. משנה פ\"ו דפאה וכב\"ה.",2,0],[4,1,"ומ\"ש והנופל מאחר המגל או מאחר היד וכו'. משנה בפ\"ד:",3,0],[4,2,"היה קוצר ביד וכו'. ירושלמי שם ובגמ' דידן פ' ראשית הגז (חולין דף קל״ז:).",1,0],[4,2,"ומ\"ש אבל התולש דברים התולשים אותם וכו' בפ' ראשית הגז:",2,0],[4,2,"היה קוצר או תולש וכו'. פ\"ד דפאה ובסיפרא מייתי לה מקרא:",3,0],[4,3,"היה קוצר ונשארה שבולת אחת שלא נקצרה וכו'. משנה בפ\"ה דפאה:",1,0],[4,4,"ומ\"ש היו שתי שבולות זו בצד זו וכו'. שם בירושלמי.",1,0],[4,4,"ומה שכתב שהרי היא כנופלת מתוך המגל ואע\"פ שעדיין לא נקצרה קשה שהרי אפילו החיצונה אינה כנופלת מתוך המגל כיון שיכולה להקצר עם הפנימית והפנימית הרי היא כאילו היא מן הקמה שבצדה ועוד שנופלת מתוך המגל היא לקט וזו אמר שנצולת והיא לבעה\"ב. וי\"ל דקאי למה שכתב לעיל בסמוך היה קוצר ונשאר שבולת אחת וכו' ואם לאו הרי היא של עניים. ואם תאמר מה טעם והלא אין לקט אלא מה שנפל וזו לא נפלה לז\"א שמאחר שנשארה היא לבדה הרי היא כנפלה וכולי עניינא חד הוא שע\"י שאמר שאם יכולה להקצר עם הקמה הרי היא של בעל השדה הוסיף ואמר שלא את עצמה בלבד הציל אלא גם את הטפילה. ואפשר דקאי נמי לדין השני שאמר שהוא לבעל השדה לפי שהפנימית נקצרת עם הקמה אבל אילו לא היתה פנימית עם הקמה לא היתה מצלת עצמה ולא לזולתה. והטעם לפי שהרי היא כנופלת וכו'.",2,0],[4,4,"ומה שכתב והשבלים שבקש הרי הם של בעל השדה. תוספתא פ\"ב:",3,0],[4,5,"הרוח שפיזרה את העמרים וכו'. משנה בפרק ה' דפאה שפיזרה את העמרים אומדים אותה כמה לקט היא ראויה לעשות ונותן לעניים רשב״ג אומר נותן לעניים בכדי נפילה ומשמע מדברי רבינו כאן דרשב״ג לא אתי לאפלוגי את״ק אלא לפרושי כמה לקט היא ראויה לעשות וכן פירש״י פרק המקבל (בבא מציעא דף ק״ה:).",1,0],[4,5,"ומ\"ש מפני שזה אונס שם בירושלמי מקשה (מ\"ש דהכא תנן) אומדין אותה כמה לקט היא ראויה לעשות (וגבי גדיש שלא לוקט תחתיו תנן) כל הנוגע בארץ הרי הוא של עניים ומשני קנס קנסו בו שגדש ע\"ג לקטן של עניים.",2,0],[4,5,"ומ\"ש וכמה הוא שיעור זה ד' קבין וכו'. שם בירושלמי ובגמ' דידן פ' המקבל:",3,0],[4,6,"לקט שנפל לארץ וכו'. משנה שם:",1,0],[4,7,"ומה שכתב ולמה אין אומדין אותה וכו' עד הרי הם לעניים. ירושלמי שם:",1,0],[4,8,"הצריך לרבץ שדהו וכו'. גם זה שם בירושלמי וכחכמים ובתוספתא ספ\"ב.",1,0],[4,8,"ומה שכתב הרי זה מדת חסידות. כן משמע שם:",2,0],[4,9,"הזרעים הנמצאים בחורי וכו'. משנה בפרק ד' דפאה חורי הנמלים שבתוך הקמה הרי הן של בעל הבית שלאחר הקוצרים העליונים לעניים והתחתונים לבעל הבית ר״מ אומר הכל לעניים שספק לקט כלקט ומשמע בירושלמי ובגמרא דידן פ' הזרוע (חולין דף קל״ד) דהלכה כר״מ.",1,0],[4,9,"ומה שכתב ואע\"פ שנמצא שחור וכו'. שם בירושלמי:",2,0],[4,10,"שבולת של לקט שנתערבה בגדיש וכו'. משנה (דף ו':) שבולת של לקט שנתערבה בגדיש מעשר שבולת אחת ונותן לו בירושלמי כיצד הוא עושה מביא שתי שבלים ואומר אם לקט הוא ה\"ז יפה ואם לאו הרי מעשרותיה קבועים בזו ונותן לו את הראשונה וחש לומר שמא אותה שקבע בה מעשרות (של) לקט היא א\"ר יונה מביא שתי שבלים ואומר אם לקט הוא הרי יפה ואם לאו הרי מעשרותיה קבועים בזו ונותן לו אחת מהן. ונראה שרבינו גורס בדרבי יונה וחוזר ואומר על השניה אם זו של לקט הרי יפה ואם לאו הרי מעשרותיה קבועים בו אי נמי שהוא מפרש דמאי דא\"ר יונה מביא שתי שבלים ואומר ה\"ק אחר שהביא שתי שבלים כמו שקדם חוזר ואומר על אותה שקבע בה מעשרות אם זו של לקט ה\"ז יפה וכו' ומ\"מ קשה מה הועיל בתקנתו הא אם אחת מהן של לקט לא נתקנה חברתה דהא תנן בפ\"ק דתרומות אין תורמין מן הלקט ומן השכחה ומן הפאה ומן ההפקר ואם תרם אין תרומתו תרומה ונראה שקושיא זו היא שהקשה וחש לומר וכו' והיאך בא רבי יונה לתרצה ועדיין הקושיא במקומה עומדת. ורבינו שמשון פירש ומשני רבי יונה דמביא שתי שבלים מלבד אותה שנותן לעני וקובע המעשרות על אחת מהן ואומר על הראשונה אם זו לקט הרי יפה ואם לאו הרי מעשרותיה קבועין על השניה ואח\"כ אומר על השניה דאם היא של לקט הרי מעשרות הראשונות קבועים על השלישית והשתא יש כאן שתי שבלים ולא ידעינן בהי מינייהו המעשרות קבועים ואין יכול ליתן לעני אלא הראשונה והא דנקט ונותן לו אחת מהן לא חש לומר ונותן לו הראשונה הואיל וכבר פירש מעיקרא עכ\"ל. אבל מדברי רבינו נראה שאינו מפריש אלא שתי שבלים בלבד ויש לתמוה עליו שאם אותה שבולת שעיכב בעה\"ב לעצמו היא של לקט לא נתקנה השבולת שנותן לעני וכן קשה איך יפרש הירושלמי שלא תיקן רבי יונה כלום לקושיא וחש לומר ויש לתמוה על הראב\"ד שלא השיגו. והר\"י קורקוס ז\"ל כתב וז\"ל לכך אני אומר מתוך הדוחק דחוזר ומתנה כן על שבולת שניה שכתב רבינו אינה הראשונה שהפריש תחלה אלא שחוזר ולוקח עוד שלישית מן הגדיש ומתנה גם עליה ואותה שקבע בה מעשרות הראשונה אין חוזר ומתנה עליה דבר אלא משום דאיכא למיחש שמא היא של לקט ונמצא שנתן לעני טבל כדברי הירושלמי לכך חוזר ולוקח אחרת ומתנה גם עליה ולכך קרא אותה שניה שהיא שניה לשל תנאי דמתנה עליה כאשר התנה על השניה שהניח וזהו חוזר ומתנה כן על שבולת שניה כלומר כאשר התנה על אותה שקבע בה המעשרות ומסתמא מן הגדיש יקח אותה ויאמר אם הראשונה לקט הרי יפה ואם היא טבל אם אותה האחרת גם כן היתה טבל הרי יפה כי כבר תקנתי עליה אותה הראשונה ואם היתה לקט מעשרות הראשונה קבועים בזאת השניה עכ\"ל. ולי נראה שרבינו מפרש שבתחילה קס\"ד שלא היה אומר אם זו של לקט וכו' אלא פעם אחת אמר נותן לו את הראשונה וכן שנה ר' יונה ואמר שחוזר ואומר על אותה שקבע בה מעשרות אם זו של לקט ה\"ז יפה כמו שפירשתי שוב אין להקשות שמא אותה שקבע בה מעשרות של לקט היא דממילא משמע שאותה שאינה של לקט יהיו מעשרותיה קבועים בה בעצמה ונותן שתיהן לעני אחת בתורת מתנה של לקט והשניה בתורת מעשר.",1,0],[4,10,"ומ\"ש ונותן לו אחת מהן. ה\"פ כשנותן לו שתיהן אחת מהן תהיה בתורת מתנות עניים של לקט והשניה תהיה בתורת מעשר והעני ימכור שתיהן לכהן ולא יפרע לו אלא דמי אחת מהן כי השניה היא של כהן כדין:",2,0],[4,11,"לא ישכור אדם את הפועל וכו'. משנה פ\"ה דפאה.",1,0],[4,11,"ומ\"ש אבל האריסין והחכירין. תוספתא פרק ג' דפאה האריסין והחכירין והמוכר קמתו לקצור מלקט בנו אחריו.",2,0],[4,11,"ומ״ש ויש לפועל להביא אשתו ובניו וכו' עד בשכרו. בפ' שנים אוחזין (בבא מציעא דף י״ב) וכר״י דאיפסקא התם הלכתא כוותיה:",3,0],[4,12,"מי שאינו מניח את העניים וכו' עד ה\"ז גוזל את העניים. משנה בפ\"ה דפאה:",1,0],[4,13,"ואסור לאדם להרביץ וכו'. בפרק שנים אוחזין (בבא מציעא דף י״ב):",1,0],[4,13,"היו שם עניים וכו'. תוספתא דפאה פ\"ג:",2,0],[4,14,"המפקיר את הלקט וכו'. ברפ\"ה דתמורה (דף כ\"ח) ופירש רש\"י עם נשירת רובו דבעי למהוי לקט (ואמר) דלהוי הפקר אפילו לעשירים:",1,0],[4,15,"איזהו פרט וכו'. משנה פ\"ו דפאה וכב\"ה:",1,0],[4,16,"היה בוצר וכרת את וכו'. משנה פ\"ז דפאה:",1,0],[4,16,"היה בוצר ומשליך לארץ וכו'. בפ\"ו דפאה בירושלמי ר' אליעזר בשם רבי חייא רבה חצי אשכול פרט תני ר' חייא חצי אשכול או אשכול שלם פרט והתניא שני גרגרים פרט רבי אמי וכו' בקוצר ומניח תחת הגפן ומשמע לרבינו דתרי אמוראי אליבא דר' חייא חד אמר חצי אשכול וחד אמר אפילו אשכול שלם. ובספר רבינו מוגה מצאתי כתוב וכן אשכול שלם שנפרט שם הוא פרט ולפי זה פסק כתני רבי חייא דמשמע שזה מה שהיה שגור בפני בני הישיבה משם רבי חייא ולא כדאמר ר' אליעזר בשמו דהוי ר\"א יחיד לגבי בני הישיבה. ועוד כיון דספיקא הוא אית לן למפסק כמאן דמזכה את העניים כדאיתא בספ\"ד דפאה ומשמע ליה דה\"פ או אשכול שלם שנפרט קאמר:",2,0],[4,16,"והמניח את הכלכלה וכו'. משנה פרק ז' דפאה:",3,0],[4,17,"איזוהי עוללת וכו'. ג\"ז משנה שם אי זו היא עוללת כל שאין לה כתף ולא נטף אם יש לה כתף או נטף לבעה\"ב אם ספק לעניים:",1,0],[4,18,"ומ\"ש איזהו כתף וכו' עד ויורדות. שם בירושלמי.",1,0],[4,18,"ומ\"ש והוא שיהיו כל הענבים שבעוללות נוגעים בפס ידו. ג\"ז שם בירושלמי איזהו כתף פסיגים זו ע\"ג זו איזהו נטף תלויות בשדרה ויורדות ר' בא בשם רב יהודה והן שיהיו כולן נוגעות בפס ידו לא כן א\"ר חייא מעשה שלקחו עוללות שבע לטריות בצפורי א\"ר חנינא שאם נתנה ע\"ג טבלא וכן שיהיו כולן נוגעות בטבלא. ורבינו שמשון כתב בירושלמי אמרינן איזהו כתף פסיגין זה ע\"ג זה איזהו נטף תלויות בשדרה ויורדות ובתוספתא תני איזהו פסיגין המחוברות בשדרה זו ע\"ג זו נטף ענבים המחוברות בשדרה ויורדות פירוש שרביט האמצעי שבאשכול היא קרוי שדרה ואשכלות קטנים הרבה מחוברין בו שבהם הגרגרים של ענבים לכן קרי ליה שדרה (דדמי לשדרה) שהצלעות מחוברות (בה) ולאותן אשכולות קטנים קרי פסיגין וכו' מלשון נתחים כדכתיב ונתח אותו לנתחיו ומתרגמינן בירושלמי ופסג יתיה לפסיגוהי שהם נתחים של אשכול וכשהפסיגין שוכבים זה ע\"ג זה כמשוי שעל כתפו של אדם נקרא כתף אבל מפוזרים בשדרה אין כאן כתף. ונטף הם גרגרים של ענבים המחוברים בשדרה עצמה מלמטה בסופה שתלויים שם ענבים הרבה ועל שענביו נוטפים מלמטה קרוי נטף עכ\"ל. ודבריו מתיישבים יותר ממה שפירש ה\"ר אליה מזרחי בבאורו לרש\"י פרשת קדושים:",2,0],[4,18,"והראב\"ד כתב לא כן הסוגיא בגמרא וכו'. וממה שהשיג הראב\"ד על דברי רבינו וכתב אלמא לענין פיטור אתמר נראה שהוא סובר שמ\"ש רבינו והוא שיהיו כל הענבים וכו' לאין לה נטף קאי לומר דלא מיקרי אין לה נטף למהוי לעניים אא\"כ כל הענבים שבעוללות נוגעים בפס ידו אבל אם אינם נוגעים לא הוי לעניים אלא לבעה\"ב. ואני אומר דאי משום הא לא קשיא מפני שאפשר לפרש דברי רבינו דקאי אאיזהו נטף דסמיך ליה לומר דלא מיקרי יש לו נטף למהוי לבעל הבית אא\"כ כל הענבים שבעוללות נוגעים בפס ידו אבל אם אינם נוגעים הוי לעניים אבל אי קשיא הא קשיא דכיון שעל מה שאמר והוא שיהיו כל הענבים שבעוללות נוגעים בפס ידו הקשו מדא\"ר חייא מעשה ששקלו עוללת אחת וכו' ותירצו שאם נתנה ע\"ג טבלא שיהיו כלן נוגעות בטבלא לא ה\"ל לכתוב שיהיו נוגעות בפס ידו דהא אידחי ליה אלא כך ה\"ל לכתוב שאם נתנה ע\"ג טבלא שיהיו כלן נוגעות בטבלא כמסקנא דגמרא. לפיכך נ\"ל שרבינו אינו מפרש כפירוש הראב\"ד אלא ה\"פ והוא שיהיו כולן נוגעות בפס ידו כלומר שאותם ענבים שבשדרה אינה זו ע\"ג זו בענין שהתחתונות נוגעות בפס ידו והעליונות אינם נוגעות אלא הם מפוזרות בענין שכלם נוגעות בפס ידו ואז הוי עוללות ולעניים ולפי שהזכיר פס ידו הוה משמע ליה דבעוללת קטן הנכנס בפס ידו הוי עוללת אבל אי הוי גדול אינו עוללת ומש\"ה אקשי ליה מדרבי חייא ושני ליה דלאו דוקא נקט פס ידו אלא אורחא דמילתא נקט וה\"ה אם היה גדול הרבה הוי עוללת והוא שכשיתנוהו ע\"ג טבלא גדולה ביותר יהיו כל הענבים נוגעים בטבלא והשתא להאי פירושא אין כאן חזרה ממה שאמר והוא שיהיו כל הענבים נוגעים בפס ידו. ויש חסרון בספרי רבינו וצריך לכתוב כך יש לה כתף ואין לה נטף או יש לה נטף ואין לה כתף הרי היא של בעל הכרם:",3,0],[4,18,"ולמה נקרא וכו'. כ\"כ גם רבינו שמשון:",4,0],[4,19,"ואין בעה\"ב חייב וכו'. וגרגיר יחידי הרי היא עוללת. משנה בפ\"ז דפאה וכחכמים:",1,0],[4,20,"זמורה שהיה בה וכו'. משנה:",1,0],[4,21,"כרם שכולו עוללות וכו'. ג\"ז משנה וכר\"ע:",1,0],[4,21,"ואין הפרט והעוללות נוהגים וכו'. בפרק הזרוע (חולין דף קל״א) בתוספתא פרק ב' דפאה:",2,0],[4,22,"ואין העניים זוכים ליקח וכו'. בפרק ז' דפאה במשנה אליבא דר\"ע.",1,0],[4,22,"ומ\"ש וכמה יבצור וכו'. שם בירושלמי:",2,0],[4,23,"המקדיש כרמו וכו'. משנה שם.",1,0],[4,23,"ומה שכתב ויתנו שכר גידולם להקדש, שם לר\"י ואמרינן בירושלמי מעשה היה והורו כר\"י:",2,0],[4,24,"הזומר את הגפן וכו'. ג\"ז משנה שם המידל בגפנים וכו'. וכת\"ק:",1,0],[4,25,"נכרי שמכר כרמו לישראל וכו'. תוספתא דפאה ספ\"ג ומסיים בה וישראל שמכר כרמו לנכרי לבצור פטור מן העוללות ואיני יודע למה השמיטו רבינו ואפשר שהטעם משום דממילא משמע שאחר מי שהיה הכרם בידו אזלינן:",1,0],[4,25,"ישראל ונכרי שהיו וכו'. בפרק ראשית הגז (חולין דף קל״ה:) שדך למעוטי שותפות נכרי ומשמע לרבינו דהיינו דוקא לפטור של נכרי בלבד וכרשב״ג דאמר התם הכי לענין תרומה בישראל ונכרי שלקחו שדה בשותפות:",2,0],[4,26,"בן לוי שנתנו לו וכו'. ירושלמי פרק ז' דפאה בן לוי שנתמנה לו מעשר טבל ומצא בתוכו עוללות ה\"ז עושה אותן תרומת מעשר במקום אחר ועוללות לאו של עני הוא ר' אבין בשם רבנן דתמן אני אומר הנקרצות עם האשכולות:",1,0],[4,26,"וכתב הראב\"ד א\"א שעושה אותו תרומת מעשר על מ בתוספתא לא אמר כן וכו'. ורבינו לאו של עניים הם ר' אבין אמ נראה שמפרש דהכי קאמר אומר אני דכי קתני עושה אותם תרומת מעשר במקום אחר דוקא בנקרצות עם האשכולות וקמ\"ל דלא גזרינן אטו אינן נקרצות עם האשכולות והתוספתא שהביא הראב\"ד אפשר דרבינו גורס חושש ואפילו אי הוה גריס אינו חושש יש לפרש דהכי קאמר אינו חושש לגזור נקרצות עם האשכול אטו אינן נקרצות:",2,0],[4,27,"מי שהיו לו חמש גפנים ובצרם וכו'. ירושלמי פרק ג' דפאה ובתוספתא פ\"ק דפאה:",1,0],[4,27,"כתב הראב\"ד ומן הפאה עכ\"ל. נראה שהיה גורס שם כן ואפשר שאע\"פ שלא היה גורס כן ומשמע ליה דכיון דפטור מן השכחה ה\"ה שפטור מן הפאה. והכי משמע שם בירושלמי ורבינו סמך על מה שכתב בפרק ב' בדין קוטף מלילות מעט מעט ומכניסן לביתו שהוא פטור אף מן הפאה וממנו למד בכרם בבוצר לאכול ענבים ששוים הם ולא בא כאן אלא ללמדנו שחייב בעוללות לפטור מן הרבעי דלא שייכי בתבואה:",2,0],[4,27,"וכתב עוד הראב\"ד אא\"כ שייר מקצתן א\"א לא כן הסוגיא אלא חייב בכל אע\"פ ששייר עכ\"ל. ומחלוקתן תלוי בפירוש הירושלמי בפרק הנזכר דגרסינן התם ר' זעירא וכו' בשם ר\"י המלקט שבלים לעיסתו אפילו כל שהוא פטור מן הפאה ר' אליעזר אמר אפילו במגל אמר ר' יוסי והוא ששייר והתני היו לו חמש גפנים והוא בוצרן ומכניסן לתוך ביתו פטור מן הפרט (ומן הערלה) ומן הרבעי וחייב בעוללת (אמר ר' יודן וכו') תמן כשבקש לאוכלן ענבים ברם הכא כשבקש לעשותן יין הדא ילפא מן ההיא וההיא ילפא מן הדא הדא ילפא מן ההיא שאם בקש לאוכלם מלילות ואפילו לא שייר וההיא ילפא מן הדא שאם בקש לשתותן יין והוא ששייר עכ\"ל. ופשטא דסוגיא משמע דכששייר גורם פיטור למה שקצר או בצר וכשנתכוון לאוכלם מלילות או ענבים פטור אפילו שייר ואם נתכוון לעיסתו או ליין חייב למה שקצר או בצר אפילו שייר וכדברי הראב\"ד ומאי דקתני בסיפא שאם בקש לשתותן והוא ששייר הוי כאילו קאמר אפילו שייר והכי קאמר שאם בקש לשתותן יין חייב והא דאיצטריך לאשמועינן דחייב בששייר דאילו לא שייר פשיטא אבל קשה לזה דאם כן מידחי מאי דאמר רבי יוסי על מלקט שבלים לעיסתו פטור והוא ששייר לכך נראה דגרסינן שאם בקש לשתותן יין חייב אא\"כ שייר דהשתא אתיא שפיר כר\"י דאמר על מלקט לעיסתו פטור והוא ששייר. ונראה שזאת היתה גירסת רבינו והר\"י קורקוס ז\"ל כתב שפשט דברי הירושלמי כדברי רבינו וה\"פ שאם בקש לשתותם יין והוא ששייר דאז פטור אבל אם לא שייר חייב והוא מ\"ש ר\"י על שבלים לעיסתו דפטור וקאמר ששייר דליין ולעיסה חד דינא אית להו:",3,0],[5,1,"העומר ששכחוהו וכו'. משנה פרק חמישי דפאה.",1,0],[5,1,"ומה שכתב שכחוהו אלו ואלו והיו שם אחרים עוברים וכו'. שם בירושלמי רבי שמעון בר יהודה משום רבי שמעון אומר אפילו חמרים שעברו וראו עומר ששכחו פועליו ושכחו בעל הבית אינו שכחה עד שישכחוהו כל אדם כך היא גירסת רבינו וסבר רבינו דרבי שמעון לפרש דברי תנא קמא אתא.",2,0],[5,1,"ומה שכתב ואפילו עומר הטמון אם נשכח הרי זה שכחה. בספרי ומייתי לה בפרק עגלה ערופה:",3,0],[5,2,"היה בעל השדה בעיר וכו'. בירושלמי ספ״ה היה עומד בעיר ואמר יודע אני שהפועלים שוכחים עומרים שבמקום פלוני ושכחוהו אינו שכחה. היה עומד בשדה ואמר יודע אני שהפועלים שוכחים עומרים שבמקום פלוני הרי זה שכחה שנאמר בשדה ושכחת ולא בעיר ושכחת ורבינו פסק בהפך משום דבפ' שנים אוחזין (בבא מציעא דף י״א) אמרינן ומנא תימרא דחצר שאינה משתמרת אי עומד בצד שדהו אין אי לא לא דתניא היה עומד בעיר ואמר יודע אני שעומר שיש לי בשדה פועלים שכחוהו לא יהא שכחה יכול לא יהא שכחה ת״ל ושכחת עומר בשדה בשדה שכחת ולא בעיר הא גופא קשיא וכו' אלא לאו הכי קאמר בשדה שכוח מעיקרו הוי שכחה זכור ולבסוף שכוח אינו שכחה מ״ט דכיון דקאי גביה הוה ליה חצירו וזכתה לו אבל בעיר אפילו זכור ולבסוף שכוח הוי שכחה מ״ט דליתיה גביה דליזכי ליה. ופסק רבינו כגמרא דידן ומשמע ליה שהירושלמי סבור כדקס״ד בגמרא דידן דקאמר ודילמא גזירת הכתוב הוא דבשדה ניהוי שכחה ובעיר לא ניהוי שכחה ואע״ג דמהדר גמרא אמר קרא יהיה לרבות שכחת העיר הירושלמי דריש להאי יהיה לדרשא אחריתי:",1,0],[5,3,"עמדו עניים בפניו או חיפוהו בקש. משנה פ\"ה דפאה עמדו עניים בפניו או שחיפוהו בקש הרי זה אינו שכחה ובירושלמי רבי יונה אמר בזוכר את הקשים.",1,0],[5,3,"ומ\"ש או שהחזיק בו וכו'. משנה פ\"ו דפאה:",2,0],[5,3,"אבל אם נטלו ממקום למקום אע\"פ שהניחו סמוך לגפה וכו'. משנה שם העומר שהוא סמוך לגפה ולגדיש לבקר ולכלים ושכחו בית שמאי אומרים אינו שכחה ובית הלל אומרים שכחה ומסיק בירושלמי לא נחלקו בית שמאי ובית הלל על העומר שהוא סמוך לגפה ולגדיש ולבקר ולכלים ושכחו שהוא שכחה ועל מה נחלקו על העומר שנטלו ונתנו בצד הגפה בצד הגדיש בצד הבקר בצד הכלים שבית שמאי אומרים אינו שכחה (מפני שזכה בו) ובית הלל אומרים שכחה וידוע דהלכה כבית הלל וזהו שכתב רבינו אע\"פ שהניחו סמוך לגפה וכו':",3,0],[5,4,"נטל עומר להוליכו לעיר וכו'. שם בירושלמי ופרק עגלה ערופה (סוטה דף מ״ה) עומר שנטלו להוליכו לעיר ונתנו על גבי חבירו ושכח את שניהם התחתון שכחה והעליון אינו שכחה רבי שמעון אומר שניהם אינם שכחה התחתון מפני שהוא מכוסה והעליון מפני שזכה בו רבי זעירא אומר בזוכר את העליון:",1,0],[5,4,"וכתב הראב\"ד הסוגיא שאמרה וכו'. כלומר וכיון דלא קי\"ל כר\"ש אלא כת\"ק אפילו בזוכר העליון התחתון שכחה לעולם ורבינו נראה שמפרש דכי אמר רבי זעירא בזוכר קאי למאי דאמר ר\"ש דהתחתון אינו שכחה וה\"ק ע\"כ לא פליג ת\"ק עליה אלא בשאינו זוכר אבל אם זוכר העליון לת\"ק נמי אין התחתון שכחה ויפה כחו של פירוש רבינו דקאי ר' זעירא את\"ק דהלכתא כוותיה:",2,0],[5,5,"עפו עמריו וכו'. בר״פ עגלה ערופה (סוטה דף מ״ה):",1,0],[5,6,"הנוטל עומר ראשון שני ושלישי וכו'. ירוש' בפ\"ו דפאה עימר את הראשון ואת השני ואת השלישי (ושכח את הרביעי) אית תניי תני אם נטל את החמישי הרי הוא שכחה ואית תנייא תני אם שהה ליטול החמישי ה\"ז שכחה אמר ר' בון בר חייא מ\"ד נוטל החמישי כשיש שם ששי מ\"ד אם שהא (כדי) ליטול (את) החמישי כשאין שם ששי אם עד שלא נטל את החמישי לא כבר נראה את הרביעי לידון בשורה את אמר שכחה וכו'. וכתב ר\"ש פי' רבי בון בר חייא בא לפרש דלא פליגי. דמ\"ד נטל את החמישי הוי רביעי שכחה אבל שהא ליטול לא כשיש בשורה שלשה עומרים דכשיעמר ג' והניח ג' נחשבה שורה הג' שהניחה ונמצא כששהא ואח\"כ עימר החמישי הוה ליה כמתחיל לעמר באמצע שורה מש\"ה תני אם נטל החמישי שלא שהא ומ\"ד דאפי' שהא הוי רביעי שכחה כשאין שם ששי דכשעימר ג' לא נשתיירו כי אם שנים דאע\"פ ששהא קודם שעימר החמישי הרי הוא כמסיים עומרו הראשון. ולכאורה נראה שיטה זו כב\"ה דאמרי שנים לעניים ושלשה לבעה\"ב עכ\"ל:",1,0],[5,7,"שני עמרים מעורבבין וכו'. גם זה ירושלמי שם. נ\"א שדה שעמריה מעורבבין וכו', היא בתוספתא פ\"ג:",1,0],[5,8,"הלוף והשום וכו'. משנה פ\"ו כחכמים ואיתא בפרק עגלה ערופה:",1,0],[5,8,"הקוצר בלילה וכו' עד תנאו בטל. גם זה משנה שם. ובמה ששנינו אם היה מתכוין ליטול הגס הגס אין לו שכחה פירש הר\"ש אם היה מתכוין ליטול הגסים ולהניח הדקים אין לו שכחה לדקים מאחר שלא נתכוין לדקים:",2,0],[5,9,"תבואה שקצרה וכו' עד אין להם שכחה. גם זה משנה שם:",1,0],[5,10,"הקוצר שהתחיל לקצור וכו'. גם זה משנה שם:",1,0],[5,11,"שנים שהתחילו לקצור וכו'. גם זה משנה שם שנים שהתחילו מאמצע שורה זה פניו לצפון וזה פניו לדרום ושכחו לפניהם ולאחריהם שלפניהם שכחה שלאחריהם אינו שכחה. ופירש ה\"ר עובדיה שנים שהתחילו מאמצע שורה של עמרים זה הפך פניו לצפון וזה הפך פניו לדרום ושכחו לפניהם לאחר שהתחילו לעמר דילגו עומר ושכחוהו הוי שכחה דקרינן ביה לא תשוב לקחתו. ולאחריהם אינו שכחה אם כשהפכו פניהם זה לצפון וזה לדרום והתחילו לעמר נשאר עומר אחד ביניהם ושכחוהו אינו שכחה לפי ששניהם סמכו זה על זה ומתוך כך נשכח עכ\"ל. וכך הם דברי רבינו שמשון ומדברי רבינו נראה שמפרש שהיו עשר שורות של עשרה עשרה עמרים מסודרות וכשהתחילו שנים מאמצע שורה זה פניו לצפון וזה פניו לדרום אם שכחו לאחריהם במקום שהתחילו ממנו אינו שכחה משום דאמרינן מאחר שהם שנים דבר רחוק הוא לומר ששכחוהו ויותר ראוי לומר שהניחו עומר זה בכוונה כדי שיהיה ראש שורה ממזרח למערב ועוד דמדהתחילו מאמצע שורה מוכח הכי דאל\"כ ה\"ל להתחיל זה מראש השורה וזה מסופה. אבל אם שכחו ממה שלפניהם אי זה עומר הוי שכחה משום דכיון שהתחיל לקצור מצפון לדרום אינו עשוי להניח עומר אחד שיהיה ראש שורה ממזרח למערב. אבל קשה לי למה תלה הדבר שלפניהם שכחה מפני שכל אחד מהם זה שלפניו הוא לאחריו של חבירו. ועוד קשה לי מה לנו שיהיה עומר זה לאחור של חבירו כיון שהוא לפני הקוצר עצמו אם מטעם שהוא לפניו אינו ראוי להיות שכחה מפני שהוא לאחורי חבירו לא הוה ליה להיות שכחה. ולכן נראה לי דמשום דבמתני' מסיים בה יחיד שהתחיל מראש השורה ושכח לפניו ולאחריו שלפניו אינו שכחה ושלאחריו שכחה מפני שהוא בבל תשוב זה הכלל כל שהוא בבל תשוב שכחה ושאינו בבל תשוב אינו שכחה ומדקתני זה הכלל משמע דקאי גם ארישא ולפיכך פירש דהא דקתני בשנים שהתחילו מאמצע שורה שלפניהם שכחה היינו לומר שאע\"פ שהיחיד שהתחיל מראש השורה ושכח לפניו אינו שכחה שנאמר לא תשוב לקחתו ואינו שכחה עד שיעבור ממנו ויניחנו לאחריו בששנים התחילו לקצור מאמצע אם שכח אחד מהם לפניו אע\"פ שלא עבר ממנו ולא הניחו לאחריו הוי שכחה מפני שהוא לאחוריו של חבירו והטעם שכיון ששנים אלו מוטל עליהם קצירת השדה ה\"ל תרוייהו כאיש אחד וכיון שאם היה בא ליטול מה ששכח חבירו היה צריך לחזור לאחוריו קרינן ביה לא תשוב לקחתו והוי שכחה וכשהתחילו מאמצע שורה דקתני שאם שכחו לאחריהם אינו שכחה הוי טעמא כדפרישית:",1,0],[5,11,"והראב\"ד כתב זה המחבר פתח בשכחת קמה וכו'. וכבר ביארתי המשניות לדעת רבינו.",2,0],[5,11,"ומ\"ש רבינו וכן השורות של עמרים וכו'. מבואר בירושלמי שם מנין לראשי שורות אמר רבי יונה כתיב כי תקצור קצירך בשדה וכו' עד כדון ראשי שורות קמה סוף שורות קמה כו' אמר רבי יונה נילף ראש שורות עומרים מראש שורות קמה וסוף שורות קמה מסוף שורות עומרים. ולא ידעתי למה תמה עליו הראב\"ד וכתב זה המחבר פתח בשכחת קמה וסיים בשכחת עמרים דהא ירושלמי הוא:",3,0],[5,12,"הקוצר ואלם אלומות אלומות וכו'. משנה בפ\"ה דפאה המעשר לכובעות ולכומסאות וכו':",1,0],[5,15,"שתי כריכות וכו'. תוספתא דפאה פרק שלישי:",1,0],[5,15,"שני עמרים וכו' שני צבורי זיתים וכו' שני הוצני פשתן וכו'. משנה בפ״ו דפאה וכתב הרא״ש הוצני פשתן כשעוקרים אותה הם כהוצי דקל ולכך קרי להו הוצני. ונראה לי דמיירי כשהזריעו ואז הוא מאכל אדם כדאיתא בר״פ המוכר פירות (בבא בתרא דף צ״ב) אבל שאר פשתן לא שייך ביה שכחה:",2,0],[5,16,"שתי גפנים וכו'. תוספתא פרק שלישי דפאה:",1,0],[5,17,"היו כל העומרים וכו'. משנה פ\"ו דפאה וכב\"ה.",1,0],[5,17,"ומ\"ש וכן אם היו של שני קבין וכו'. שם בירושלמי:",2,0],[5,18,"העומר שיש בו סאתים וכו'. משנה בפ\"ו דפאה.",1,0],[5,18,"ומ\"ש שאע\"פ שכולם סאתים סאתים. טעמו משום דכיון דמולא גדיש ממעטין ליה אף זה בכלל.",2,0],[5,18,"ומ\"ש שכח שני עמרים וכו'. שם במשנה ופסק כת\"ק.",3,0],[5,18,"ומ\"ש וכן יראה לי וכו'. פשוט הוא שגם זה בכלל הטעם שנתנו שם במשנה ובירושלמי:",4,0],[5,19,"קמה שיש בה סאתים וכו' עד אינה שכחה. משנה שם.",1,0],[5,19,"ומ\"ש רואים את השבלים הדקות וכו'. זה פירוש הוא מה ששנינו שם אפילו היא של טופח רואים אותה כאילו היא ענבה של שעורים וכן פירשו בירושלמי:",2,0],[5,20,"שכח סאה תבואה עקורה וכו' עד אלא שניהם שכחה. משנה בפ\"ו דפאה וכתנא קמא:",1,0],[5,21,"השוכח עומר בצד הקמה וכו'. משנה שם הקמה מצלת את העומר ולא את הקמה והעומר אינו מציל לא את העומר ולא את הקמה אי זו היא קמה שהיא מצלת את העומר כל שאינה שכחה אפילו קלח אחד והטעם בירושלמי ובספרי פ' כי תצא.",1,0],[5,21,"ומה שכתב אבל אם שכח עומר וכו' אפילו היה בו סאתים וכו'. הכי משמע ממתני':",2,0],[5,21,"אין קמת חבירו מצלת וכו' עד ממין העומר. שם בירושלמי ותוספתא פרק ששי פלוגתא ופסק כחכמים:",3,0],[5,22,"השוכח אילן וכו'. משנה פרק שביעי דפאה כל זית שיש לו שם בשדה אפילו כזית הנטופה בשעתו ושכחו אינו שכחה וכו' ושאר כל הזיתים שנים שכחה ושלשה אינם שכחה. ופירש רבינו שמשון שנים שכחה באילן עצמו קאמר ששכח שני זיתי אילן וסתמא כבית הלל דאמרי בפרקין דלעיל שנים לעניים עכ\"ל, וכך הם דברי רבינו פה:",1,0],[5,22,"והראב\"ד כתב השוכח אילן בין האילנות וכו'. א\"א זה אינו מחוור כלל עכ\"ל. ונראה שטעמו משום דלא מסתבר ליה שאילן אחד או שני אילנות או שלשה שלימים יהיו שכחה דהא דקתני כל זית שיש לו שם בשדה ושכחו אינו שכחה דמשמע דזית שאין לו שם בשדה הוי שכחה נראה שפירש הראב\"ד דהיינו לומר שאם שכח קצת זיתים אם יש לו שם בשדה אינה שכחה ואם אין לו שם בשדה הוי שכחה ועל דרך זה יתפרש מאי דקתני סיפא ושאר כל הזיתים שנים שכחה שלשה אינם שכחה והדבר ברור כמה דחוק פירוש זה ומאי דקשיא ליה היאך יתכן לשכוח אילן או שנים שלימים מי שרואה מאתים אילני זיתים נטועים יחד לא יפלא אם ישכחו שלשה אילנות או יותר. והר\"י קורקוס ז\"ל כתב נראה שכוונת הר\"א על מה שכתב רבינו שאפילו שיש בו סאתים שהוא סובר דכי היכי דעומר שיש בו סאתים אינו שכחה גם אילן שיש בו סאתים אין ראוי שיהיה שכחה ואפשר דכל שכן הוא ולכך כתב אין זה מחוור כלל. אבל דעת רבינו דכיון שלא הוזכר אלא בעומר איכא לפלוגי דבשלמא בעומרים עומר שיש בו סאתים חשיב ולא הוי שכחה אבל באילנות אילן שיש בו סאתים לא חשיב כולי האי לגבי שאר אילנות שנאמר שלא יהיה שכחה וטעמיה דילפינן מינייהו גבי עומר דכיון שיש בו סאתים גדיש נקרא ולא עומר או מדכתיב לא תשוב לקחתו לא שייכי באילן ופרק שביעי שנינו כל זית שיש לו שם וכו' משמע דדוקא אילן שיש לו שם באותם שלשה דברים הוא דאינו שכחה דעל ידי כך זכור אבל סאתים פירות באילן לא חשיבי להיות זכור על ידי כך עכ\"ל:",2,0],[5,24,"ומ\"ש היה מסויים בדעתו וכו' עד זה מסיים את זה. ירושלמי שם.",1,0],[5,24,"ומ\"ש היתה כל שדהו וכו'. ג\"ז שם בירושלמי:",2,0],[5,24,"בד\"א שלא התחיל וכו'. שם במשנה זית שיש בו סאתים ושכחו אינו שכחה בד\"א בזמן שלא התחיל בו אבל אם התחיל בו אפילו כזית הנטופה בשעתו ושכחו יש לו שכחה. ובתוספתא פ\"ג כל הזית שיש לו שם בשדה כזית הנטופה בשעתו ושכחו אינו שכחה בד\"א בזמן שלא התחיל בו אבל אם התחיל בו ושכחו הרי זה שכחה עד שיהא בו סאתים.",3,0],[5,24,"ומ\"ש והוא שיהיה הנשאר בו פחות מסאתים וכו': כתב הראב\"ד מן המשנה נראה שאינו כן. ואני אומר כי דברי רבינו מבוארים בתוספתא ועל פיה צריך לפרש המשנה וכן פירשוה רבינו ורבינו שמשון וכן משמע בירושלמי.",4,0],[5,24,"ועל מ\"ש רבינו אבל סאתים אינו שכחה אא\"כ שכח כל האילן כמו שביארנו: וכתב הראב\"ד א\"א אין זה מחוור כלל עכ\"ל. נראה שטעמו דלא משמע ליה שישכח אילן שלם וכבר כתבתי בסמוך דפשטא דמתניתין כדברי רבינו ומלשון זה שכתב רבינו בד\"א שלא התחיל באילן זה המפורסם וכו' אבל סאתים אינו שכחה אלא א\"כ שכח כל האילן כמו שביארנו נראה שאפילו בזית שאינה נטופה אם התחיל בו ויש במה שנשאר סאתים אינו שכחה. וא\"כ לפי זה נמצא דבאינה נטופה טפי הוי שכחה כששכח כל האילן מכשהתחיל בו ושכחו בכזית נטופה הוי איפכא וזה דבר תימה שאם בכזית נטופה אם שכח האילן אינו שכחה כשהתחיל בו ושכחו הוי שכחה אלמא כשהתחיל בו ושכחו ראוי להיות שכחה יותר. וא\"כ בשאר אילנות שכששכח כל האילן הוי שכחה כשהתחיל בו ושכחו מכל שכן דהוה ליה להיות שכחה. ותירץ הר\"י קורקוס ז\"ל דבשאר אילנות בהתחיל בו ושכחו נמי הוי שכחה אפילו נשאר בו",5,0],[5,24,"סאתים ומ\"ש אחר כך שכח כל האילן פירושו אלא אם כן אינו נטופה דאף דשכח כל האילן הוי שכחה כמו שביארנו:",6,0],[5,25,"זית העומד וכו'. משנה שם זית שנמצא עומד בין שלש שורות של שני מלבנים ושכחו אינו שכחה:",1,0],[5,25,"ולמה אמרו זית בלבד וכו'. שם במשנה רבי יוסי אומר אין שכחה לזיתים ואמרינן בירושלמי לא אמר ר' יוסי אלא בראשונה שלא היו הזיתים מצויים שבא אדריאנוס הרשע והחריב את כל הארץ אבל עכשיו שהזיתים מצויים יש להם שכחה:",2,0],[5,25,"וכתב הראב\"ד א\"א אינו אלא לדעת ר' יוסי עכ\"ל. כלומר וכיון דיחידאה הוא לא הוה ליה למפסק כוותיה. ולדעת רבינו יש לומר דגם הוא ז\"ל לא פסק כוותיה אלא דאע\"ג דלא קיי\"ל כר' יוסי מ\"מ יליף מיניה רבינו לרבנן שהטעם שהזכירו במשנה באלו הדינים זית יותר מאילן אחר מפני שהיה חשוב בארץ ישראל באותו זמן:",3,0],[5,26,"איזהו שכחה וכו'. משנה שם ובמקום מה שכתוב במשנה וברגליות משיעבור הימנה כתב רבינו ובכרם משיעבור מן הגפן ומן הגפנים ונראה שט\"ס הוא ואפשר לקיים הגירסא וכתב כן רבינו מפני שאינו ניכר ששכחה עד שיבצור גפן אחר ויעבור הימנו ומתניתין לישנא קלילא נקט.",1,0],[5,26,"ומ\"ש בדלית ובדקל וכו' עד כל סביביו, תוספתא דפאה ספ\"ג:",2,0],[5,26,"בד\"א בשלא התחיל וכו' אבל אם התחיל בו. וכך כתוב בספרי רבינו של דפוס ורבינו שמשון כתב שט\"ס הוא בתוספתא וצריך להגיה בד\"א כשהתחיל בו אבל אם לא התחיל בו. כך מצאתי בספר רבינו מוגה:",3,0],[5,27,"המפקיר את כרמו וכו'. בס״פ הזרוע (חולין קל״ד:) ופ״ק דתמורה (דף ו').",1,0],[5,27,"ומ\"ש אבל אם זכה מן ההפקר וכו'. כן פירש\"י שם:",2,0],[6,2,"מתנה אחרת ששית יש לעניים וכו'. ומ\"ש מפריש ממנו אחד מחמשים וכו'. בפרק ד' דתרומות:",1,0],[6,3,"ומ\"ש ואח\"כ מפריש מהשאר אחד מעשרה וכו'. בפרק ה' דמעשר שני:",1,0],[6,4,"על הסדר הזה מפרישין בשנה ראשונה וכו' אבל בשלישי ובששי מן השבוע וכו' והוא הנקרא מעשר עני וכו'. בפ\"ק דר\"ה (דף י\"ב):",1,0],[6,5,"שנת השמיטה כולה הפקר וכו'. סיפרי פרשת ראה.",1,0],[6,5,"ומ\"ש ובחו\"ל שאין בה שמטת קרקע מפרישין בארץ מצרים ובעמון ומואב מעשר ראשון ומעשר עני וכו' אבל בארץ שנער מפרישין בשביעית מעשר שני, בפ\"ד דידים.",2,0],[6,5,"ומ\"ש רבינו והל\"מ שיהו מפרישין בארץ עמון ומואב מעשר עני בשביעית. שם במשנה א\"ר אליעזר כן ומ\"מ משמע דלאו דוקא הלכה למשה מסיני ממש קאמר דהא קתני התם דעמון ומואב הוא מעשר זקנים וכן בדין דהא חוצה לארץ מן התורה אין נוהגים בה לא תרומה ולא מעשרות וכן כתב רבינו עצמו בתחלת הלכות תרומות וכתב עוד שם שחכמים הראשונים התקינו שיהיו נוהגות אף בארץ מצרים וכן פירש ר\"ש הלכה למשה מסיני לאו דוקא אלא כהל\"מ ולכן יש לתמוה על רבינו שסתם וכתב שדבר זה הלכה למשה מסיני וצריך לומר שהעתיק לשון המשנה והרואה דבריו בתחלת הלכות תרומות ידע דלאו דוקא:",3,0],[6,6,"מעשר ראשון שלקח הלוי וכו'. בפ\"ה דמעשר שני ובספרי סוף פרשת קרח:",1,0],[6,7,"בעל השדה שעברו עליו עניים וכו'. פרק בכל מערבין (דף כ':) וירושלמי פ\"ח דפאה:",1,0],[6,8,"ומ\"ש אם מן החטים וכו'. משנה שם.",1,0],[6,8,"ומ\"ש ומן האורז רובע הקב וכו' עד אתרוג אחד. שם בירושלמי.",2,0],[6,8,"ומ\"ש ואם נתן לו משאר פירות וכו'. שם במשנה פאה פרק ח':",3,0],[6,9,"היה לו דבר מועט וכו'. גם זה שם במשנה:",1,0],[6,10,"ומעשר עני המתחלק בגורן וכו' עד ונותנו לכל עני שירצה. בפרק הזרוע חולין (דף קל\"א):",1,0],[6,11,"היה לו מעשר בגורן וכו'. משנה בפרק שמיני דפאה היה נוטל מחצה ונותן מחצה ונתפרשה בירושלמי. וכתב רבינו כרבי יונה:",1,0],[6,12,"במה דברים אמורים שאינו נותן לעני וכו'. תוספתא פרק ד' דפאה:",1,0],[6,13,"באו איש ואשה לבית וכו'. פרק נושאין (יבמות ק'):",1,0],[6,13,"אב ובנו וכו'. ירושלמי פ\"ה דפאה:",2,0],[6,14,"שני עניים וכו'. משנה שם:",1,0],[6,15,"המקבל שדה לקצור וכו'. גם זה משנה שם וכרבי יהודה דאמר אימתי לפרש דברי תנא קמא:",1,0],[6,16,"המוכר את שדהו וכו'. גם זה משנה שם וירושלמי.",1,0],[6,16,"ומ\"ש אע\"פ שעדיין לא נתן דמים ואפילו לוה הדמים וכו':",2,0],[6,17,"מעשר עני אין פורעין ממנו מלוה. תוספתא פ\"ד דפאה.",1,0],[6,17,"ומ\"ש ואין מוציאין אותו מהארץ לחוצה לארץ וכו'. ספרי פרשת ראה:",2,0],[7,2,"מצות עשה ליתן צדקה וכו': וכל הרואה עני מבקש וכו':",1,0],[7,4,"לפי מה שחסר העני וכו' ואחר כך משיאין לו אשה. בפרק מציאת האשה (כתובות דף ס\"ז):",1,0],[7,5,"בא העני ושאל וכו' וכמה עד חמישית. בפ' נערה שנתפתתה (כתובות דף נ') ובירושלמי ריש פאה ומייתי לה מדכתיב וכל אשר תתן לי עשר אעשרנו לך ופירש״י עשר אעשרנו שני עישורים ה״ל חומש. ובפ' מציאת האשה (כתובות דף ס״ז:) מקשה מהא דאל יבזבז יותר מחומש להא דר' אבהו כי קא ניחא נפשיה בזבזיה לפלגא דממוניה ומשני הני מילי מחיים שמא ירד מנכסיו אבל לאחר מיתה לית לן בה ורבינו לא מיירי הכא אלא בחיים.",1,0],[7,5,"ומ\"ש ואחד מעשרה בנכסיו בינוני פחות מכאן עין רעה: ולעולם לא ימנע אדם עצמו משלישית השקל בשנה. בפ\"ק דבתרא (דף ט'):",2,0],[7,5,"ואפילו עני המתפרנס מן הצדקה וכו'. פ\"ק דגיטין (דף ז'):",3,0],[7,6,"עני שאין מכירים אותו וכו'. פ\"ק דבתרא (דף ט'):",1,0],[7,7,"מפרנסים ומכסים עניי עכו״ם וכו'. בס״פ הנזקין (גיטין דף ס״א):",1,0],[7,7,"ועני המחזר על הפתחים וכו'. פ\"ק דבתרא:",2,0],[7,7,"ואסור להחזיר את העני וכו':",3,0],[7,8,"אין פוחתין לעני וכו'. משנה בסוף פאה (דף י':).",1,0],[7,8,"ומה שכתב ואם לן וכו'. שם לן נותנין לו פרנסת לינה ובפרק קמא דבתרא (דף ט') ובפרק כל כתבי (שבת דף קי\"ח) מאי פרנסת לינה פוריא ובי סדיא.",2,0],[7,8,"ומ\"ש ושמן וקטנית בתוספתא דסוף פאה.",3,0],[7,8,"ומ\"ש ואם שבת נותנין לו מזון שלש סעודות משנה בסוף פאה.",4,0],[7,8,"ומ\"ש שמוסיפין לו בשבת דג וירק שם בתוספתא.",5,0],[7,8,"ומ״ש ואם היו מכירים אותו וכו'. הכי משמע בפרק מציאת האשה (כתובות דף ס״ז):",6,0],[7,9,"עני שאינו רוצה ליקח צדקה וכו'. בפרק מציאת האשה תנו רבנן אין לו ואינו רוצה להתפרנס מהצדקה נותנים לו לשום הלואה וחוזרים ונותנין לו לשום מתנה דברי ר\"מ וחכמים אומרים נותנין לו לשום מתנה וחוזרים ונותנים לו לשום הלואה לשום מתנה הא לא שקיל אמר רבא לפתוח לו לשום מתנה ופסק רבינו כחכמים:",1,0],[7,9,"ועשיר המרעיב את עצמו וכו'. שם ופסק כחכמים:",2,0],[7,10,"מי שאינו רוצה ליתן צדקה וכו'. בפרק נערה שנתפתתה (כתובות דף מ\"ט):",1,0],[7,10,"וממשכנין [על] הצדקה וכו'. בפ\"ק דבתרא (דף ח'):",2,0],[7,11,"אדם שוע וכו'. שם:",1,0],[7,12,"אין פוסקין צדקה על יתומים וכו' עד מותר. שם:",1,0],[7,12,"גבאי צדקה וכו' עד ועניותן. בסוף בבא קמא (דף קי\"ט):",2,0],[7,13,"עני שהוא קרובו וכו'. בפרק איזהו נשך (בבא מציעא דף ע״א):",1,0],[7,14,"מי שהלך בסחורה וכו' עד כמו שיראה לו. בפרק בני העיר (מגילה דף כ״ז):",1,0],[7,15,"האומר תנו מאתים דינר לבית הכנסת וכו' עד סוף הפרק. תוספתא פרק הגוזל ופרק חזקת:",1,0],[8,1,"הצדקה הרי היא בכלל הנדרים וכו'. בפירקא קמא דראש השנה (דף ו').",1,0],[8,1,"ומה שכתב ואם התנה וכו'. וכן אם התנה וכו':",2,0],[8,2,"המתפיס בצדקה חייב כשאר הנדרים וכו'. פ\"ק דנדרים (דף ז') בעיא דאיפשיטא באת\"ל כדעת רבינו:",1,0],[8,3,"הנודר צדקה ולא ידע כמה נדר וכו'. נלמד ממתני' פרק בתרא דמנחות (דף ק\"ה):",1,0],[8,4,"אחד האומר סלע זו צדקה וכו' עד אסור לשנותו. פירקא קמא דערכין (דף ו'):",1,0],[8,4,"ואם רצו הגבאים לצרף וכו'. פירקא קמא דבבא דבתרא (דף ח' ע\"ב):",2,0],[8,5,"היה לעניים הנאה וכו'. פ\"ק דערכין והביאו הרי\"ף פרק ד' וה':",1,0],[8,7,"מי שהתנדב מנורה וכו' עד ומכרוהו לעצמם. שם ובירושלמי פרק קמא דשקלים:",1,0],[8,8,"עכו\"ם שהתנדב לבדק הבית וכו'. פרק קמא דערכין (דף ו':) תני חדא עכו\"ם שהתנדב נדבה לבדק הבית מקבלים ממנו ותניא אידך אין מקבלים א\"ר אילא א\"ר יוחנן ל\"ק הא בתחלה הא בסוף דאמר רב אסי א\"ר יוחנן בתחלה אפי' מים ומלח אין מקבלים מהם בסוף דבר המסויים אין מקבלים דבר שאינו מסויים מקבלים. ופירש\"י דבר המסויים שנראה בעין אין מקבלין מהם דגנאי הוא ועוד שמתפארים בו. ורבינו מפרש שמ\"ש הא בתחלה הא בסוף היינו לומר הא בתחלה הא בדיעבד ורש\"י פירש בע\"א.",1,0],[8,8,"ומ\"ש אבל לבית הכנסת מקבלים מהם לכתחלה וכו' שם (דף ו') עכו\"ם שהתנדב קורה ושם כתוב עליה בודקין אותו אם אמר כדעת ישראל הפרשתיה יגוד וישתמש במותר ואם לאו טעונה גניזה חיישינן שמא בלבו לשמים ומסיק דה\"ה אע\"ג דאין שם כתוב עליה בעיא גניזה והא קמ\"ל דאע\"ג דשם כתוב עליה יגוד וישתמש במותר ופירש\"י טעונה גניזה ואסורה בהנאה דחיישינן שמא בלבו לשמים לשם הקדש הילכך יגנז ובזמן הזה עסקינן דהקדש אסור בהנאה וכו'. יגוד יחתוך מקום השם ויגנוז החתיכה וישתמש במותר ויבננו בבית הכנסת עכ\"ל. ונראה מדברי רבינו דכי תניא וישתמש במותר וישתמש לבנותה בבהכ\"נ קאמר:",2,0],[8,8,"ואין מקבלים מהם לחומת ירושלים וכו'. פרק קמא דשקלים בירושלמי:",3,0],[8,9,"אסור לישראל וכו'. בפרק זה בורר (סנהדרין דף כ\"ו:):",1,0],[8,9,"ומלך או שר וכו'. בפירקא קמא דבבא בתרא (דף י'):",2,0],[8,10,"פדיון שבויים קודם לפרנסת עניים וכו'. ואין לך מצוה רבה כפדיון שבויים. שם (דף ח'):",1,0],[8,11,"אנשי העיר שגבו וכו'. שם (דף ג':) אמר רב חסדא לא ליסתור איניש בי כנישתא עד דבני בי כנישתא אחריתי וכו' אמר ליה רבינא לרב אשי גבי זוזי ומחתי מאי אמר ליה דילמא מתרמי להו פדיון שבויים ויהבי להו (רמי ליבני) שריגי ליבני והדרי הודרי וכו' א\"ל דילמא דמתרמי להו פדיון שבויים מזבני ויהבי להו א\"ה אפילו בנו נמי א\"ל דירתיה דאינשי לא מזבני:",1,0],[8,14,"אין פודין את השבויים וכו' עד אסור לפדות. בפ' השולח (גיטין דף מ״ה). ופסק כלישנא דלא ליגררו ולייתו וכן פסק הרי״ף:",1,0],[8,15,"האשה קודמת לאיש וכו' עד לפי שאין דרכו בכך. בסוף הוריות (דף י\"ג):",1,0],[8,16,"יתום ויתומה וכו'. בפ' מציאת האשה (כתובות דף ס״ז):",1,0],[8,18,"היו לפנינו עניים הרבה וכו' עד ת\"ח קודם. משנה בסוף הוריות (דף י\"ג).",1,0],[8,18,"ומ\"ש וכל הגדול בחכמה וכו'. ומ\"ש ואם היה אחד מהם רבו או אביו כו':",2,0],[9,1,"כל עיר שיש בה ישראל וכו'. כן משמע בפרק קמא דבתרא (דף ח':) ובסוף פאה:",1,0],[9,4,"בתעניות מחלקים וכו'. בפרק אחד דיני ממונות (סנהדרין דף ל״ה) וירושלמי סוף פאה:",1,0],[9,5,"הקופה אינה נגבית אלא בשנים וכו'. משנה בסוף פאה.",1,0],[9,5,"ומ\"ש מותר להאמין לאחד המעות של קופה. בפ\"ק דבתרא (דף ח').",2,0],[9,5,"ומ\"ש ואינה נחלקת אלא בשלשה וכו' משנה בסוף פאה.",3,0],[9,5,"ומ\"ש והתמחוי נגבה בשלשה וכו'. פרק קמא דבתרא:",4,0],[9,12,"התמחוי נגבה בכל יום וכו' עד כל צרכי קבורה. בפ\"ק דבתרא:",1,0],[9,12,"כתב מהרי\"ק ואשר תמהת על רבינו משה שכתב ל' יום לקופה ג' חדשים לתמחוי ואמרת דבגמרא דידן ברייתא הויא איפכא. דעו כי חילוק נוסחאות היא בספרים שהרי מצאתיה בשני ספרים כדברי רבינו משה ויש הוכחה לגירסת רבינו דבתוספתא דפאה כתוב שלשים יום לקופה ולגירסא זו הטעם מפני שהקופה יותר מוכרחת מן התמחוי ואין לך מקום שאין בו קופה ויש מקומות שלא נהגו בתמחוי:",2,0],[9,14,"מי שיש לו מזון שתי סעודות וכו' עד ומצוה ליתן לו. משנה בסוף פאה:",1,0],[9,14,"ומ״ש במה דברים אמורים בכלי אכילה ושתיה וכו'. בפ' מציאת האשה (כתובות דף ס״ח) שם אוקימתא דרבא.",2,0],[9,14,"ומ\"ש במה דברים אמורים קודם שיגיע לגבות מן העם וכו'. שם אוקימתא דרב פפא שלענין דינא לא פליגי וכן דעת הרי\"ף:",3,0],[9,15,"בעה\"ב שהיה מהלך וכו'. משנה בפרק חמישי דפאה וכחכמים:",1,0],[9,17,"מי שהיו לו בתים וכו' עד שאינו דחוק למכור. בפ\"ק דב\"ק (דף ז') תניא הרי שהיו לו בתים שדות וכרמים ואינו מוצא למכור מאכילין אותו מעשר עני עד מחצה הוי בה רבה היכי דמי אי דזול ארעתא דכולי עלמא ודיליה נמי זלא בהדייהו אפילו פורתא נמי לא ליספו ליה ואי דאייקור ארעתא דכולי עלמא ודיליה איידי דעייל ונפיק אזוזי זלא ארעיה אפילו טובא נמי ליספו ליה (והדר אמר רבה) לא נצרכה אלא דביומי ניסן יקרא ארעא וביומי תשרי זלא ארעא דכולי עלמא נטרי עד ניסן ומזבני והאי הואיל ואצטריכו ליה זוזי השתא עד פלגא אורחיה למיזל טפי לאו אורחיה למיזל. זו היא גירסת הרי\"ף ופירשו התוספות גירסא זו דמיירי בששויים הרבה ועד מחצה היינו עד שימצא מי שיקנה אותם בחצי דמיהם לכל הפחות. ואפי' פורתא נמי לא ליספו ליה פירוש אפילו הוזלו כ\"כ שאפילו במחצה לא יתנו לו לא ליספו כיון דזיל ארעתא דכולי עלמא ושוות מאתים לפי הזול. אפי' טובא נמי ליספו ליה פי' אפי' שמוצא שיקנו טפי ממחצה מ\"מ ליספו ליה עד שימצא למכור בשוויין דאין מוצא למכור לפי שרואים שהוא דחוק:",1,0],[9,17,"וכתב רבינו ירוחם שכ\"פ הר\"ר יונה וסיים בה לא נצרכה וכו'. כלומר אם ישוו מחצה בדמיהם ימכרם ולא יטול מעשר עני. טפי לאו אורחיה כלומר ויש לו לתלות שבשביל דחקו למכור אינו מוצא חצי שוויין שישוו בניסן ומאכילין אותו מעשר עני עד שימצא חצי דמיהם. וכתב סמ\"ג כל רבותינו הקדמונים בצרפת אומרים שזו הגירסא ופי' זה עיקר. ולאפוקי מגירסת רש\"י ופירושו. ודברי רבינו פשוטים שהם כגי' רי\"ף אלא שמ\"ש שמאכילין אותו מעשר עני עד חצי דמיהם הוא שלא כמו שפירשו לדעת הרי\"ף שהם פירשוה לדעתו דהיינו לומר שמאכילין אותו מעשר עני עד שימצא מי שיקנה אותם בחצי דמיהם ורבינו נראה שמפרש מאכילים אותו עד חצי דמי הקרקעות משום דעד פלגא אורחיה למיזל טפי לא ואע\"פ שאפשר לדחוק ולפרש לשון רבינו דה\"ק מאכילין אותו עד שימצא למכור בחצי דמיהם מכל מקום פשט לשונו משמע הכי אלא דה\"ק מאכילין אותו עד חצי דמי הקרקעות. ורבינו השמיט דין זול ארעתא דכולי עלמא ודיליה נמי זל בהדייהו אפילו פורתא נמי לא ליספו ליה והטעם משום דמילתא דפשיטא היא:",2,0],[9,18,"עני שגבו לו וכו' עד ליורשיו. משנה פרק שני דשקלים:",1,0],[9,19,"עני שנתן פרוטה וכו' עד סוף הפרק. תוספתא פ\"ד דפאה:",1,0],[10,1,"חייבין אנו להזהר וכו'. ואין ישראל נגאלים אלא בצדקה וכו'. פרק קמא דבתרא (דף י') ופרק תולין שבת (דף קל\"ט):",1,0],[10,2,"לעולם אין אדם מיעני וכו': כל המרחם מרחמין עליו וכו'. פרק הערל (יבמות דף ע\"ט):",1,0],[10,3,"כל המעלים עינו וכו'. בפרק מציאת האשה (כתובות דף ס״ח) ובספרי פרשת ראה:",1,0],[10,4,"כל הנותן צדקה לעני וכו':",1,0],[10,5,"שאל העני ממך וכו'. במדרש משלי על פסוק טוב ארוחת ירק הנותן פרוטה לעני מתברך בשש ברכות וכו' והמפייסו בדברים מתברך באחת עשרה:",1,0],[10,6,"הכופה אחרים וכו'. מימרא דר\"א פ\"ק דבתרא:",1,0],[10,6,"(ומ\"ש ועל גבאי צדקה וכיוצא בהם נאמר ומצדיקי הרבים ככוכבים. שם):",2,0],[10,7,"שמונה מעלות וכו'. מעלה גדולה שאין למעלה ממנה זה המחזיק ביד ישראל שמך וכו':",1,0],[10,8,"ומ״ש פחות מזה הנותן צדקה לעניים ולא ידע למי נתן ולא ידע העני ממי לקח. פרק לולב וערבה (סוכה דף מ״ט:) ופ״ק דבתרא (דף י') שתי צדקות הללו למה וכו' ואי זו היא שמצילתו ממיתה משונה נותנה ואינו יודע למי נותנה נוטלה ואינו יודע ממי נוטלה.",1,0],[10,8,"ומ\"ש כגון לשכת חשאין וכו'. משנה בפ\"ה דשקלים (משנה ו').",2,0],[10,8,"ומ\"ש ולא יתן אדם תוך קופה של צדקה וכו'. בפרק קמא דבבא בתרא (דף י'):",3,0],[10,9,"ומ״ש כגון גדולי החכמים וכו'. בפ' מציאת האשה (כתובות דף ס״ז:) עובדא דמר עוקבא:",1,0],[10,10,"ומה שכתב כגון גדולי החכמים שהיו צוררים המעות בסדיניהם וכו'. שם רבי אבא הוה צייר זוזי בסודריה ושדי ליה לאחוריה וממצי נפשיה ביני עניי ומצלי עיניה מרמאי. ופירש רש\"י מצלי עיניה מטה עיניו כלפי אחוריו לראות שלא יבא רמאי ויתירם שעושה עצמו עני, והעניים באים ומתירים אותם:",1,0],[10,15,"גדולי החכמים היו נותנים פרוטה לעני וכו'. פרק קמא דבתרא (דף י'):",1,0],[10,16,"הנותן מזונות לבניו ולבנותיו וכו'. בפרק נערה שנתפתתה (כתובות דף נ') ופירוש הגדולים שהם גדולים יותר משש.",1,0],[10,16,"ומ\"ש וכן הנותן מזונות לאביו ולאמו וכו': וכל המאכיל ומשקה עניים ויתומים על שלחנו וכו':",2,0],[10,17,"צוו חכמים שיהיו בני ביתו וכו'. בפרק קמא דאבות:",1,0],[10,18,"לעולם ידחוק אדם עצמו וכו' וכן צוו חכמים ואמרו עשה שבתך חול וכו'. בפרק ע\"פ (דף קי\"ב).",1,0],[10,18,"ומ\"ש ואפי' היה חכם ומכובד וכו' מוטב לפשוט עור בהמות נבילות וכו'. שם (דף קי\"ג) ובפרק יש נוחלין:",2,0],[10,18,"גדולי החכמים היו מהם חוטבי עצים. הלל בפרק שלישי דיומא (דף ל\"ה:).",3,0],[10,18,"ומה שכתב ונושאי הקורות. רב ששת ר״פ מי שאחזו (גיטין דף ס״ז:).",4,0],[10,18,"ושואבי מים לגנות. רב הונא בפ' שני דייני גזירות (כתובות דף ק״ה).",5,0],[10,18,"ועושים הברזל והפחמים. רבי יהושע בפרק תפלת השחר (ברכות דף כ״ח:):",6,0],[10,19,"כל מי שאינו צריך ליטול וכו'. משנה בסוף פאה:",1,0],[10,19,"וכל מי שצריך ליטול וכו'. ירושלמי בסוף פאה:",2,0],[10,19,"ומה שכתב וכל מי שצריך וכו'. משנה שם:",3,0],[10,19,"סליקו הלכות מתנות עניים בס\"ד",4,0]]);
